"""Recoverable idempotent JSON-file inbox.

Public API::

    box = Inbox(path)                    # missing file == empty inbox
    record = box.submit(identifier, payload)
    record = box.start_next()            # None when nothing pending
    record = box.finish(identifier)
    records = box.snapshot()

A record is ``{"id": str, "payload": <JSON value>, "status": str}`` with one of
the statuses ``pending``, ``running``, ``completed`` or ``interrupted``.  The
persistent document is ``{"version": 1, "records": [...]}`` and keeps records in
original submission order.

Durability model: every mutation builds the *next* in-memory state first, writes
it to a same-directory temporary file with flush + ``os.fsync``, and only calls
``os.replace`` (atomic on Windows and POSIX) before swapping the new state into
the instance.  A failing save therefore propagates ``OSError`` while the
instance keeps exactly the state it had before the operation.
"""

from __future__ import annotations

import copy
import json
import math
import os
import tempfile

__all__ = ["Inbox"]

DOCUMENT_VERSION = 1

PENDING = "pending"
RUNNING = "running"
COMPLETED = "completed"
INTERRUPTED = "interrupted"

VALID_STATUSES = frozenset({PENDING, RUNNING, COMPLETED, INTERRUPTED})

_MAX_ID_LENGTH = 64

_DOCUMENT_FIELDS = frozenset({"version", "records"})
_RECORD_FIELDS = frozenset({"id", "payload", "status"})

_DUMP_KWARGS = {
    "ensure_ascii": False,
    "separators": (",", ":"),
    "allow_nan": False,
}


def _canonical(payload):
    """Canonical text used to decide whether two payloads are the same."""
    return json.dumps(payload, sort_keys=True, **_DUMP_KWARGS)


def _validate_identifier(identifier):
    if not isinstance(identifier, str):
        raise ValueError("identifier must be a string")
    if not identifier:
        raise ValueError("identifier must be a nonempty string")
    if len(identifier) > _MAX_ID_LENGTH:
        raise ValueError("identifier must be at most %d characters" % _MAX_ID_LENGTH)


def _validate_payload(value):
    """Raise ValueError unless *value* is a JSON value (finite numbers only)."""
    if value is None or isinstance(value, bool):
        return
    if isinstance(value, str):
        return
    if isinstance(value, int):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("payload numbers must be finite")
        return
    if isinstance(value, list):
        for item in value:
            _validate_payload(item)
        return
    if isinstance(value, dict):
        for key, item in value.items():
            if not isinstance(key, str):
                raise ValueError("payload object keys must be strings")
            _validate_payload(item)
        return
    raise ValueError("payload is not a JSON value: %r" % (type(value).__name__,))


def _detached(record):
    """Deep copy of a record so callers can never mutate stored state."""
    return {
        "id": record["id"],
        "payload": copy.deepcopy(record["payload"]),
        "status": record["status"],
    }


def _normalize_record(raw):
    if not isinstance(raw, dict):
        raise ValueError("record must be a JSON object")
    if set(raw) != _RECORD_FIELDS:
        raise ValueError("record must have exactly 'id', 'payload', 'status'")
    identifier = raw["id"]
    _validate_identifier(identifier)
    status = raw["status"]
    if not isinstance(status, str) or status not in VALID_STATUSES:
        raise ValueError("unknown record status: %r" % (status,))
    payload = raw["payload"]
    _validate_payload(payload)
    return {"id": identifier, "payload": payload, "status": status}


def _document_records(document):
    if not isinstance(document, dict):
        raise ValueError("inbox document must be a JSON object")
    if set(document) != _DOCUMENT_FIELDS:
        raise ValueError("inbox document must have exactly 'version' and 'records'")
    version = document["version"]
    if isinstance(version, bool) or not isinstance(version, int) or version != DOCUMENT_VERSION:
        raise ValueError("unsupported inbox document version: %r" % (version,))
    raw_records = document["records"]
    if not isinstance(raw_records, list):
        raise ValueError("'records' must be a JSON array")
    records = []
    seen = set()
    for raw in raw_records:
        record = _normalize_record(raw)
        if record["id"] in seen:
            raise ValueError("duplicate record id: %r" % (record["id"],))
        seen.add(record["id"])
        records.append(record)
    return records


def _reject_constant(name):
    raise ValueError("invalid JSON constant in inbox file: %s" % (name,))


class Inbox:
    """Single-process, single-writer, durable and idempotent JSON inbox."""

    def __init__(self, path):
        self.path = path
        self._path = os.fspath(path)
        self._records = self._load()
        # Recovery: a crash may leave records marked running.  They are not
        # restarted; they become interrupted and that recovery is persisted
        # before the constructor returns.
        recovered = [
            {"id": record["id"], "payload": record["payload"], "status": INTERRUPTED}
            if record["status"] == RUNNING
            else record
            for record in self._records
        ]
        if recovered != self._records:
            self._commit(recovered)

    # ------------------------------------------------------------------ API

    def submit(self, identifier, payload):
        """Register *identifier* once; returns the record (detached)."""
        _validate_identifier(identifier)
        _validate_payload(payload)
        canonical = _canonical(payload)
        for record in self._records:
            if record["id"] != identifier:
                continue
            if _canonical(record["payload"]) == canonical:
                # Idempotent replay: current state, no re-execution, no reset.
                return _detached(record)
            raise ValueError("conflicting payload for existing id: %r" % (identifier,))
        record = {"id": identifier, "payload": copy.deepcopy(payload), "status": PENDING}
        self._commit(self._records + [record])
        return _detached(record)

    def start_next(self):
        """Mark the first pending record running, or return None."""
        for record in self._records:
            if record["status"] == RUNNING:
                raise RuntimeError("a record is already running")
        for index, record in enumerate(self._records):
            if record["status"] != PENDING:
                continue
            started = {"id": record["id"], "payload": record["payload"], "status": RUNNING}
            records = list(self._records)
            records[index] = started
            self._commit(records)
            return _detached(started)
        return None

    def finish(self, identifier):
        """Mark a running record completed; completing twice is a no-op."""
        for index, record in enumerate(self._records):
            if record["id"] != identifier:
                continue
            status = record["status"]
            if status == COMPLETED:
                return _detached(record)
            if status != RUNNING:
                raise ValueError("cannot finish a %s record" % (status,))
            finished = {"id": record["id"], "payload": record["payload"], "status": COMPLETED}
            records = list(self._records)
            records[index] = finished
            self._commit(records)
            return _detached(finished)
        raise KeyError(identifier)

    def snapshot(self):
        """Detached deep copy of the records in submission order."""
        return [_detached(record) for record in self._records]

    # --------------------------------------------------------- persistence

    def _load(self):
        try:
            with open(self._path, "r", encoding="utf-8") as handle:
                text = handle.read()
        except FileNotFoundError:
            return []
        document = json.loads(text, parse_constant=_reject_constant)
        return _document_records(document)

    def _commit(self, records):
        """Persist *records* first; publish them only after a successful save."""
        self._save(records)
        self._records = records

    def _save(self, records):
        document = {"version": DOCUMENT_VERSION, "records": records}
        text = json.dumps(document, **_DUMP_KWARGS)
        directory = os.path.dirname(os.path.abspath(self._path))
        os.makedirs(directory, exist_ok=True)
        descriptor, temporary = tempfile.mkstemp(
            dir=directory, prefix=os.path.basename(self._path) + ".", suffix=".tmp"
        )
        try:
            with os.fdopen(descriptor, "w", encoding="utf-8", newline="\n") as handle:
                handle.write(text)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, self._path)
            temporary = None
        finally:
            if temporary is not None:
                try:
                    os.unlink(temporary)
                except OSError:
                    pass

