class Decoder:
    """Incremental decoder for frames of the form ``<len>:<payload>,``.

    A frame is the ASCII decimal byte length of the payload, a colon, exactly
    that many UTF-8 payload bytes, and a trailing comma.  Frames are decoded
    incrementally across :meth:`feed` calls and terminated with :meth:`finish`.
    """

    _DIGIT_ZERO = 0x30
    _DIGIT_NINE = 0x39
    _COLON = 0x3A
    _COMMA = 0x2C

    def __init__(self, max_size=1024):
        if isinstance(max_size, bool) or not isinstance(max_size, int):
            raise ValueError("max_size must be a nonnegative int")
        if max_size < 0:
            raise ValueError("max_size must be a nonnegative int")
        self.max_size = max_size
        self._phase = "len"
        self._length = 0
        self._len_started = False
        self._len_zero = False
        self._payload = bytearray()
        self._closed = False

    def feed(self, data):
        if self._closed:
            raise ValueError("decoder is closed")
        if not isinstance(data, (bytes, bytearray)):
            raise TypeError("data must be bytes or bytearray")

        results = []
        for byte in data:
            if self._phase == "len":
                if self._COLON == byte:
                    if not self._len_started:
                        self._fail("empty length")
                    self._phase = "payload" if self._length else "comma"
                elif self._DIGIT_ZERO <= byte <= self._DIGIT_NINE:
                    if self._len_zero:
                        self._fail("leading zero in length")
                    digit = byte - self._DIGIT_ZERO
                    if not self._len_started:
                        self._len_started = True
                        self._length = digit
                        if digit == 0:
                            self._len_zero = True
                        elif self._length > self.max_size:
                            self._fail("length exceeds max_size")
                    else:
                        self._length = self._length * 10 + digit
                        if self._length > self.max_size:
                            self._fail("length exceeds max_size")
                else:
                    self._fail("malformed length")
            elif self._phase == "payload":
                self._payload.append(byte)
                if len(self._payload) == self._length:
                    self._phase = "comma"
            else:  # "comma"
                if self._COMMA != byte:
                    self._fail("missing frame terminator")
                results.append(self._decode_payload())
                self._reset_frame()
        return results

    def finish(self):
        if self._closed:
            raise ValueError("decoder is closed")
        if self._phase != "len" or self._len_started:
            self._fail("incomplete frame at EOF")
        self._closed = True
        return None

    def _reset_frame(self):
        self._phase = "len"
        self._length = 0
        self._len_started = False
        self._len_zero = False
        self._payload = bytearray()

    def _decode_payload(self):
        try:
            return bytes(self._payload).decode("utf-8")
        except UnicodeDecodeError:
            self._fail("invalid UTF-8 payload")

    def _fail(self, message):
        self._closed = True
        raise ValueError(message)

