import copy
import json
import math
import os
import tempfile

_VERSION = 1
_DOCUMENT_KEYS = {"version", "records"}
_RECORD_KEYS = {"id", "payload", "status"}
_STATUSES = ("pending", "running", "completed", "interrupted")
_MAX_ID_LENGTH = 64


def _validate_id(identifier):
    if not isinstance(identifier, str):
        raise ValueError("id must be a string")
    if not identifier:
        raise ValueError("id must be nonempty")
    if len(identifier) > _MAX_ID_LENGTH:
        raise ValueError("id must be at most 64 characters")


def _validate_payload(value, _seen=None):
    if value is None:
        return
    if isinstance(value, bool):
        return
    if isinstance(value, int):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("numbers must be finite")
        return
    if isinstance(value, str):
        return
    if isinstance(value, (list, dict)):
        if _seen is None:
            _seen = set()
        marker = id(value)
        if marker in _seen:
            raise ValueError("circular reference in payload")
        _seen.add(marker)
        try:
            if isinstance(value, list):
                for item in value:
                    _validate_payload(item, _seen)
            else:
                for key, item in value.items():
                    if not isinstance(key, str):
                        raise ValueError("object keys must be strings")
                    _validate_payload(item, _seen)
        finally:
            _seen.discard(marker)
        return
    raise ValueError("not a JSON value: %r" % (type(value),))


def _canonical(payload):
    return json.dumps(
        payload,
        sort_keys=True,
        ensure_ascii=False,
        separators=(",", ":"),
        allow_nan=False,
    )


class Inbox:
    def __init__(self, path):
        self.path = path
        records = self._load()
        recovered = False
        for record in records:
            if record["status"] == "running":
                record["status"] = "interrupted"
                recovered = True
        if recovered:
            self._persist(records)
        self._records = records

    def submit(self, identifier, payload):
        _validate_id(identifier)
        _validate_payload(payload)
        canonical = _canonical(payload)
        for record in self._records:
            if record["id"] == identifier:
                if _canonical(record["payload"]) == canonical:
                    return copy.deepcopy(record)
                raise ValueError("conflicting payload for id %r" % (identifier,))
        record = {
            "id": identifier,
            "payload": copy.deepcopy(payload),
            "status": "pending",
        }
        new_records = list(self._records)
        new_records.append(record)
        self._persist(new_records)
        self._records = new_records
        return copy.deepcopy(record)

    def start_next(self):
        for record in self._records:
            if record["status"] == "running":
                raise RuntimeError("a record is already running")
        for index, record in enumerate(self._records):
            if record["status"] == "pending":
                updated = dict(record)
                updated["status"] = "running"
                new_records = list(self._records)
                new_records[index] = updated
                self._persist(new_records)
                self._records = new_records
                return copy.deepcopy(updated)
        return None

    def finish(self, identifier):
        for index, record in enumerate(self._records):
            if record["id"] == identifier:
                status = record["status"]
                if status == "completed":
                    return copy.deepcopy(record)
                if status == "running":
                    updated = dict(record)
                    updated["status"] = "completed"
                    new_records = list(self._records)
                    new_records[index] = updated
                    self._persist(new_records)
                    self._records = new_records
                    return copy.deepcopy(updated)
                raise ValueError("cannot finish record in state %r" % (status,))
        raise KeyError(identifier)

    def snapshot(self):
        return copy.deepcopy(self._records)

    def _load(self):
        path = os.fspath(self.path)
        if not os.path.exists(path):
            return []
        with open(path, "r", encoding="utf-8") as handle:
            document = json.load(handle)
        return self._parse_document(document)

    def _parse_document(self, document):
        if not isinstance(document, dict):
            raise ValueError("document must be an object")
        if set(document.keys()) != _DOCUMENT_KEYS:
            raise ValueError("invalid document schema")
        if type(document["version"]) is not int or document["version"] != _VERSION:
            raise ValueError("unsupported document version")
        raw_records = document["records"]
        if not isinstance(raw_records, list):
            raise ValueError("records must be a list")
        records = []
        seen = set()
        for raw in raw_records:
            records.append(self._parse_record(raw, seen))
        return records

    def _parse_record(self, raw, seen):
        if not isinstance(raw, dict):
            raise ValueError("record must be an object")
        if set(raw.keys()) != _RECORD_KEYS:
            raise ValueError("invalid record schema")
        identifier = raw["id"]
        _validate_id(identifier)
        if identifier in seen:
            raise ValueError("duplicate id %r" % (identifier,))
        seen.add(identifier)
        status = raw["status"]
        if status not in _STATUSES:
            raise ValueError("invalid status %r" % (status,))
        payload = raw["payload"]
        _validate_payload(payload)
        return {
            "id": identifier,
            "payload": copy.deepcopy(payload),
            "status": status,
        }

    def _persist(self, records):
        document = {
            "version": _VERSION,
            "records": [
                {
                    "id": record["id"],
                    "payload": record["payload"],
                    "status": record["status"],
                }
                for record in records
            ],
        }
        text = json.dumps(document, ensure_ascii=False, allow_nan=False)
        path = os.fspath(self.path)
        directory = os.path.dirname(os.path.abspath(path))
        os.makedirs(directory, exist_ok=True)
        descriptor, temporary = tempfile.mkstemp(
            dir=directory, prefix=".inbox-", suffix=".tmp"
        )
        try:
            with os.fdopen(descriptor, "w", encoding="utf-8", newline="\n") as handle:
                handle.write(text)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, path)
        except BaseException:
            try:
                os.remove(temporary)
            except OSError:
                pass
            raise

"""Recoverable, idempotent inbox backed by a single JSON file.

The public contract is documented in README.md.  Only the Python standard
library is used and all writes go through a same-directory temporary file that
is flushed, fsync'ed and atomically moved into place with ``os.replace``.
"""

import copy
import json
import math
import os
import tempfile

_STATES = ("pending", "running", "completed", "interrupted")
_MAX_ID_LENGTH = 64


def _validate_id(identifier):
    if not isinstance(identifier, str):
        raise ValueError("id must be a string")
    if not identifier or len(identifier) > _MAX_ID_LENGTH:
        raise ValueError("id must be a nonempty string of at most 64 characters")


def _validate_payload(payload):
    """Recursively validate that *payload* is a JSON value."""
    if payload is None or isinstance(payload, bool):
        return
    if isinstance(payload, int):
        return
    if isinstance(payload, float):
        if not math.isfinite(payload):
            raise ValueError("numbers must be finite")
        return
    if isinstance(payload, str):
        return
    if isinstance(payload, list):
        for item in payload:
            _validate_payload(item)
        return
    if isinstance(payload, dict):
        for key, value in payload.items():
            if not isinstance(key, str):
                raise ValueError("object keys must be strings")
            _validate_payload(value)
        return
    raise ValueError("payload is not a JSON value")


def _canonical(payload):
    """Canonical form used for payload equality comparisons."""
    return json.dumps(
        payload,
        sort_keys=True,
        ensure_ascii=False,
        separators=(",", ":"),
        allow_nan=False,
    )


def _reject_constant(value):
    raise ValueError("invalid JSON constant: %s" % (value,))


def _validate_document(raw):
    """Validate a persistent document and return detached records."""
    if not isinstance(raw, dict):
        raise ValueError("document must be a JSON object")
    if set(raw.keys()) != {"version", "records"}:
        raise ValueError("document must contain exactly 'version' and 'records'")
    if type(raw["version"]) is not int or raw["version"] != 1:
        raise ValueError("unsupported document version")
    records = raw["records"]
    if not isinstance(records, list):
        raise ValueError("'records' must be a list")

    seen = set()
    validated = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError("each record must be a JSON object")
        if set(record.keys()) != {"id", "payload", "status"}:
            raise ValueError("each record must have exactly id, payload and status")
        identifier = record["id"]
        _validate_id(identifier)
        if identifier in seen:
            raise ValueError("duplicate stored id: %r" % (identifier,))
        seen.add(identifier)
        status = record["status"]
        if status not in _STATES:
            raise ValueError("invalid record status: %r" % (status,))
        payload = record["payload"]
        _validate_payload(payload)
        validated.append(
            {
                "id": identifier,
                "payload": copy.deepcopy(payload),
                "status": status,
            }
        )
    return validated


class Inbox:
    def __init__(self, path):
        self.path = os.fspath(path)
        self._records = self._load()

    # -- persistence ----------------------------------------------------

    def _load(self):
        try:
            with open(self.path, "r", encoding="utf-8") as handle:
                text = handle.read()
        except FileNotFoundError:
            return []

        # json.JSONDecodeError is a ValueError subclass, so malformed JSON is
        # reported as ValueError as required.  The original file is never
        # touched during loading.
        raw = json.loads(text, parse_constant=_reject_constant)
        records = _validate_document(raw)

        if any(record["status"] == "running" for record in records):
            recovered = [
                {
                    "id": record["id"],
                    "payload": record["payload"],
                    "status": (
                        "interrupted"
                        if record["status"] == "running"
                        else record["status"]
                    ),
                }
                for record in records
            ]
            self._save(recovered)
            records = recovered
        return records

    def _save(self, records):
        document = {"version": 1, "records": records}
        text = json.dumps(document, ensure_ascii=True, allow_nan=False)
        self._write_atomic(text)

    def _write_atomic(self, text):
        directory = os.path.dirname(self.path) or "."
        os.makedirs(directory, exist_ok=True)

        fd, temp_path = tempfile.mkstemp(
            prefix=".inbox-", suffix=".tmp", dir=directory
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
                handle.write(text)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temp_path, self.path)
            temp_path = None
        finally:
            if temp_path is not None:
                try:
                    os.unlink(temp_path)
                except OSError:
                    pass

    # -- public API ------------------------------------------------------

    def snapshot(self):
        return copy.deepcopy(self._records)

    def submit(self, identifier, payload):
        _validate_id(identifier)
        _validate_payload(payload)
        canonical = _canonical(payload)

        for record in self._records:
            if record["id"] == identifier:
                if _canonical(record["payload"]) == canonical:
                    return copy.deepcopy(record)
                raise ValueError("conflicting payload for id %r" % (identifier,))

        new_record = {
            "id": identifier,
            "payload": copy.deepcopy(payload),
            "status": "pending",
        }
        new_records = list(self._records)
        new_records.append(new_record)
        self._save(new_records)
        self._records = new_records
        return copy.deepcopy(new_record)

    def start_next(self):
        if any(record["status"] == "running" for record in self._records):
            raise RuntimeError("a record is already running")

        for index, record in enumerate(self._records):
            if record["status"] == "pending":
                new_record = {
                    "id": record["id"],
                    "payload": record["payload"],
                    "status": "running",
                }
                new_records = list(self._records)
                new_records[index] = new_record
                self._save(new_records)
                self._records = new_records
                return copy.deepcopy(new_record)
        return None

    def finish(self, identifier):
        for index, record in enumerate(self._records):
            if record["id"] != identifier:
                continue
            status = record["status"]
            if status == "completed":
                return copy.deepcopy(record)
            if status != "running":
                raise ValueError("cannot finish a %s record" % (status,))
            new_record = {
                "id": record["id"],
                "payload": record["payload"],
                "status": "completed",
            }
            new_records = list(self._records)
            new_records[index] = new_record
            self._save(new_records)
            self._records = new_records
            return copy.deepcopy(new_record)
        raise KeyError(identifier)

"""A durable, recoverable, idempotent JSON-file inbox.

See README.md for the public contract.  Only the Python standard library is
used.
"""

import copy
import json
import math
import os
import tempfile

_VALID_STATUSES = frozenset({"pending", "running", "completed", "interrupted"})
_RECORD_KEYS = frozenset({"id", "payload", "status"})
_VERSION = 1
_MAX_ID_LENGTH = 64


def _validate_identifier(identifier):
    """Validate a record identifier or raise ValueError."""
    if not isinstance(identifier, str):
        raise ValueError("id must be a string")
    if len(identifier) == 0:
        raise ValueError("id must not be empty")
    if len(identifier) > _MAX_ID_LENGTH:
        raise ValueError("id must be at most %d characters" % _MAX_ID_LENGTH)
    return identifier


def _validate_payload(value):
    """Validate that value is a JSON value or raise ValueError.

    Accepted: null, bool, finite int/float, str, list of JSON values,
    string-keyed dict of JSON values.
    """
    if value is None or isinstance(value, bool):
        return
    if isinstance(value, int):
        # bool is handled above; remaining ints are fine (arbitrary precision
        # integers are valid JSON numbers).
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("payload contains a non-finite number")
        return
    if isinstance(value, str):
        return
    if isinstance(value, list):
        for item in value:
            _validate_payload(item)
        return
    if isinstance(value, dict):
        for key, item in value.items():
            if not isinstance(key, str):
                raise ValueError("payload object keys must be strings")
            _validate_payload(item)
        return
    raise ValueError("unsupported payload type: %s" % type(value).__name__)


def _canonical(payload):
    """Return the canonical serialisation used for payload comparison."""
    try:
        return json.dumps(
            payload,
            sort_keys=True,
            ensure_ascii=False,
            separators=(",", ":"),
            allow_nan=False,
        )
    except (TypeError, ValueError) as exc:
        raise ValueError("payload is not a valid JSON value") from exc


class Inbox:
    """A single-process, single-writer durable JSON-file inbox."""

    def __init__(self, path):
        self.path = path
        self._path = os.fspath(path)
        self._directory = os.path.dirname(os.path.abspath(self._path))
        self._records = []
        self._load()

    # ------------------------------------------------------------------
    # Loading and validation
    # ------------------------------------------------------------------
    def _load(self):
        try:
            with open(self._path, "r", encoding="utf-8") as handle:
                text = handle.read()
        except FileNotFoundError:
            self._records = []
            return

        try:
            document = json.loads(text)
        except RecursionError as exc:
            raise ValueError("malformed inbox file") from exc
        except ValueError as exc:
            raise ValueError("malformed inbox file") from exc

        try:
            records = self._validate_document(document)
        except RecursionError as exc:
            raise ValueError("invalid inbox document") from exc

        # Recover: any record left "running" by a previous process is now
        # interrupted.  Persist the recovery before returning.
        recovered = False
        for record in records:
            if record["status"] == "running":
                record["status"] = "interrupted"
                recovered = True
        if recovered:
            self._save(records)
        self._records = records

    @staticmethod
    def _validate_document(document):
        if not isinstance(document, dict):
            raise ValueError("inbox document must be an object")
        version = document.get("version")
        if (
            isinstance(version, bool)
            or not isinstance(version, int)
            or version != _VERSION
        ):
            raise ValueError("unsupported inbox version")
        if "records" not in document:
            raise ValueError("inbox document is missing records")
        raw_records = document["records"]
        if not isinstance(raw_records, list):
            raise ValueError("inbox records must be a list")

        records = []
        seen = set()
        for raw in raw_records:
            record = Inbox._validate_record(raw)
            if record["id"] in seen:
                raise ValueError("duplicate record id: %r" % (record["id"],))
            seen.add(record["id"])
            records.append(record)
        return records

    @staticmethod
    def _validate_record(raw):
        if not isinstance(raw, dict):
            raise ValueError("record must be an object")
        if frozenset(raw.keys()) != _RECORD_KEYS:
            raise ValueError("record must have exactly id, payload and status")
        identifier = _validate_identifier(raw["id"])
        status = raw["status"]
        if not isinstance(status, str) or status not in _VALID_STATUSES:
            raise ValueError("invalid record status")
        payload = raw["payload"]
        _validate_payload(payload)
        return {"id": identifier, "payload": payload, "status": status}

    # ------------------------------------------------------------------
    # Persistence
    # ------------------------------------------------------------------
    def _save(self, records):
        """Durably persist records, atomically replacing the destination."""
        document = {"version": _VERSION, "records": records}
        text = json.dumps(document, ensure_ascii=False, allow_nan=False)

        os.makedirs(self._directory, exist_ok=True)
        fd, tmp_path = tempfile.mkstemp(
            prefix=".inbox-", suffix=".tmp", dir=self._directory
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as handle:
                handle.write(text)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(tmp_path, self._path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    def _commit(self, records):
        """Persist records, then publish them as the new in-memory state."""
        self._save(records)
        self._records = records

    # ------------------------------------------------------------------
    # Queries
    # ------------------------------------------------------------------
    def _find(self, identifier):
        for record in self._records:
            if record["id"] == identifier:
                return record
        return None

    def snapshot(self):
        """Return a detached deep copy of all records in submission order."""
        return copy.deepcopy(self._records)

    # ------------------------------------------------------------------
    # Mutations
    # ------------------------------------------------------------------
    def submit(self, identifier, payload):
        """Validate and durably store a new pending record.

        Submitting a duplicate id with an identical payload returns the
        current record without changing state.  A conflicting payload raises
        ValueError and changes nothing.
        """
        _validate_identifier(identifier)
        try:
            _validate_payload(payload)
            new_key = _canonical(payload)
        except RecursionError as exc:
            raise ValueError("payload is too deeply nested") from exc

        existing = self._find(identifier)
        if existing is not None:
            if _canonical(existing["payload"]) != new_key:
                raise ValueError("conflicting payload for id %r" % (identifier,))
            return copy.deepcopy(existing)

        record = {
            "id": identifier,
            "payload": copy.deepcopy(payload),
            "status": "pending",
        }
        records = copy.deepcopy(self._records)
        records.append(record)
        self._commit(records)
        return copy.deepcopy(record)

    def start_next(self):
        """Mark the first pending record running and return it.

        Raises RuntimeError if any record is already running.  Returns None if
        there is no pending record.
        """
        for record in self._records:
            if record["status"] == "running":
                raise RuntimeError("a record is already running")

        index = None
        for position, record in enumerate(self._records):
            if record["status"] == "pending":
                index = position
                break
        if index is None:
            return None

        records = copy.deepcopy(self._records)
        records[index]["status"] = "running"
        self._commit(records)
        return copy.deepcopy(records[index])

    def finish(self, identifier):
        """Mark a running record completed and return it.

        Finishing an already completed record is an idempotent no-op.  A
        missing id raises KeyError and any other state raises ValueError.
        """
        index = None
        for position, record in enumerate(self._records):
            if record["id"] == identifier:
                index = position
                break
        if index is None:
            raise KeyError(identifier)

        record = self._records[index]
        if record["status"] == "completed":
            return copy.deepcopy(record)
        if record["status"] != "running":
            raise ValueError(
                "cannot finish record %r in state %r"
                % (identifier, record["status"])
            )

        records = copy.deepcopy(self._records)
        records[index]["status"] = "completed"
        self._commit(records)
        return copy.deepcopy(records[index])

