class Decoder:
    _LENGTH = 0
    _PAYLOAD = 1
    _COMMA = 2

    def __init__(self, max_size=1024):
        if isinstance(max_size, bool) or not isinstance(max_size, int):
            raise ValueError("max_size must be a nonnegative int")
        if max_size < 0:
            raise ValueError("max_size must be nonnegative")
        self._max_size = max_size
        self._failed = False
        self._closed = False
        self._reset_frame()

    def _reset_frame(self):
        self._state = self._LENGTH
        self._length = 0
        self._digits = 0
        self._expected = 0
        self._payload = bytearray()

    def _check_live(self):
        if self._failed or self._closed:
            raise ValueError("decoder is no longer usable")

    def feed(self, data):
        self._check_live()
        if not isinstance(data, (bytes, bytearray)):
            raise TypeError("data must be bytes or bytearray")
        if isinstance(data, bytearray):
            data = bytes(data)
        results = []
        try:
            i = 0
            n = len(data)
            while i < n:
                if self._state == self._LENGTH:
                    b = data[i]
                    i += 1
                    if 48 <= b <= 57:
                        d = b - 48
                        if self._digits == 0 and d == 0:
                            self._digits = 1
                            self._length = 0
                        else:
                            if self._digits == 1 and self._length == 0:
                                raise ValueError("leading zero in length")
                            self._length = self._length * 10 + d
                            self._digits += 1
                            if self._length > self._max_size:
                                raise ValueError("length exceeds max_size")
                    elif b == 0x3A:
                        if self._digits == 0:
                            raise ValueError("empty length")
                        self._expected = self._length
                        self._payload = bytearray()
                        self._state = self._COMMA if self._expected == 0 else self._PAYLOAD
                    else:
                        raise ValueError("invalid byte in length")
                elif self._state == self._PAYLOAD:
                    remaining = self._expected - len(self._payload)
                    available = n - i
                    take = remaining if remaining < available else available
                    self._payload += data[i:i + take]
                    i += take
                    if len(self._payload) == self._expected:
                        self._state = self._COMMA
                else:
                    b = data[i]
                    i += 1
                    if b != 0x2C:
                        raise ValueError("expected comma")
                    try:
                        results.append(bytes(self._payload).decode("utf-8"))
                    except UnicodeDecodeError:
                        raise ValueError("invalid utf-8 payload")
                    self._reset_frame()
        except ValueError:
            self._failed = True
            self._reset_frame()
            raise
        return results

    def finish(self):
        self._check_live()
        if self._state == self._LENGTH and self._digits == 0:
            self._closed = True
            return None
        self._failed = True
        self._reset_frame()
        raise ValueError("incomplete frame at EOF")

