"""Command line interface for receipt summaries.

Usage:
    python -m receipt_tools.cli INPUT.jsonl OUTPUT.csv
"""

from __future__ import annotations

import csv
import io
import json
import os
import sys
import tempfile

from .model import summarize

__all__ = ["main"]


def _read_records(path: str):
    with open(path, "r", encoding="utf-8") as handle:
        for line in handle:
            if not line.strip():
                continue
            yield json.loads(line)


def _render_csv(rows) -> str:
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["customer", "count", "total"])
    for row in rows:
        writer.writerow([row["customer"], row["count"], row["total"]])
    return buffer.getvalue()


def _write_atomic(path: str, content: str) -> None:
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".receipt_tmp_", suffix=".csv")
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            handle.write(content)
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def main(argv: list[str] | None = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    if len(args) != 2:
        sys.stderr.write("usage: python -m receipt_tools.cli INPUT.jsonl OUTPUT.csv\n")
        return 2

    input_path, output_path = args
    try:
        rows = summarize(_read_records(input_path))
        content = _render_csv(rows)
    except (OSError, json.JSONDecodeError, ValueError, TypeError) as exc:
        sys.stderr.write(f"error: {exc}\n")
        return 1

    try:
        _write_atomic(output_path, content)
    except OSError as exc:
        sys.stderr.write(f"error: {exc}\n")
        return 1

    return 0


if __name__ == "__main__":
    sys.exit(main())

