"""Core receipt summary logic.

Public API:
    summarize(records) -> list[dict]
"""

from __future__ import annotations

import re
from collections.abc import Iterable, Mapping
from decimal import Decimal, ROUND_HALF_UP

__all__ = ["summarize"]

_AMOUNT_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?")
_VALID_STATUSES = frozenset({"paid", "void"})
_CENT = Decimal("0.01")


def _validate_record(record: object) -> tuple[str, Decimal, str]:
    """Validate a single receipt and return (customer, amount, status).

    Raises ValueError for any missing, malformed, or invalid field.
    """
    if not isinstance(record, Mapping):
        raise ValueError("receipt must be a mapping/dict")

    try:
        raw_customer = record["customer"]
    except (KeyError, TypeError) as exc:
        raise ValueError("receipt missing 'customer'") from exc
    try:
        raw_amount = record["amount"]
    except (KeyError, TypeError) as exc:
        raise ValueError("receipt missing 'amount'") from exc
    try:
        raw_status = record["status"]
    except (KeyError, TypeError) as exc:
        raise ValueError("receipt missing 'status'") from exc

    if not isinstance(raw_customer, str):
        raise ValueError("customer must be a string")
    customer = raw_customer.strip()
    if not customer:
        raise ValueError("customer must be a nonempty string")

    if not isinstance(raw_amount, str) or _AMOUNT_RE.fullmatch(raw_amount) is None:
        raise ValueError("amount must match [0-9]+(?:\\.[0-9]+)?")
    amount = Decimal(raw_amount)

    if not isinstance(raw_status, str) or raw_status not in _VALID_STATUSES:
        raise ValueError("status must be 'paid' or 'void'")

    return customer, amount, raw_status


def summarize(records: Iterable[Mapping]) -> list[dict]:
    """Summarize receipt records.

    Every record is validated (including ``void`` records). Only ``paid``
    records contribute to counts and totals. Totals are summed exactly with
    :class:`~decimal.Decimal` and rounded once per customer using
    ``ROUND_HALF_UP``.
    """
    counts: dict[str, int] = {}
    totals: dict[str, Decimal] = {}

    for record in records:
        customer, amount, status = _validate_record(record)
        if status != "paid":
            continue
        counts[customer] = counts.get(customer, 0) + 1
        totals[customer] = totals.get(customer, Decimal(0)) + amount

    result: list[dict] = []
    for customer in sorted(totals):
        total = totals[customer].quantize(_CENT, rounding=ROUND_HALF_UP)
        result.append(
            {
                "customer": customer,
                "count": counts[customer],
                "total": str(total),
            }
        )
    return result

