import re

_PARAM_RE = re.compile(r"^:([A-Za-z_][A-Za-z0-9_]*)$")


class Router:
    def __init__(self):
        self.routes = []

    @staticmethod
    def _segments(value):
        return tuple(part for part in value.split("/") if part != "")

    def add(self, pattern, handler):
        if not isinstance(pattern, str) or not pattern.startswith("/"):
            raise ValueError("pattern must be a string starting with '/'")
        if "?" in pattern or "#" in pattern:
            raise ValueError("pattern may not contain '?' or '#'")

        segments = self._segments(pattern)
        seen = set()
        for segment in segments:
            if segment.startswith(":"):
                match = _PARAM_RE.match(segment)
                if match is None:
                    raise ValueError("invalid parameter segment: %r" % (segment,))
                name = match.group(1)
                if name in seen:
                    raise ValueError("duplicate parameter name: %r" % (name,))
                seen.add(name)

        for index, (key, _) in enumerate(self.routes):
            if key == segments:
                self.routes[index] = (key, handler)
                return
        self.routes.append((segments, handler))

    def resolve(self, path):
        if not isinstance(path, str) or not path.startswith("/"):
            raise ValueError("path must be a string starting with '/'")

        cut = len(path)
        for marker in ("?", "#"):
            position = path.find(marker)
            if position != -1 and position < cut:
                cut = position
        parts = self._segments(path[:cut])

        best_handler = None
        best_params = None
        best_static = -1

        for key, handler in self.routes:
            if len(key) != len(parts):
                continue
            params = {}
            static = 0
            for wanted, actual in zip(key, parts):
                if wanted.startswith(":"):
                    params[wanted[1:]] = actual
                elif wanted == actual:
                    static += 1
                else:
                    break
            else:
                if static > best_static:
                    best_static = static
                    best_handler = handler
                    best_params = params

        if best_handler is None:
            raise KeyError(path)
        return best_handler, best_params

