"""Recoverable idempotent JSON-file inbox.

Single-process, single-writer. The persistent document is
``{'version': 1, 'records': [...]}`` with records kept in original
submission order. Only the Python standard library is used.
"""

import copy
import json
import math
import os
import tempfile

VALID_STATUSES = ("pending", "running", "completed", "interrupted")

_DOCUMENT_KEYS = frozenset(("version", "records"))
_RECORD_KEYS = frozenset(("id", "payload", "status"))


def _validate_id(identifier):
    if not isinstance(identifier, str):
        raise ValueError("id must be a string")
    if len(identifier) == 0 or len(identifier) > 64:
        raise ValueError("id must be nonempty and at most 64 characters")


def _validate_payload(value):
    """Recursively validate that *value* is a JSON value.

    Accepts string-keyed objects, lists, strings, finite numbers, bool and
    null.  Anything else raises ValueError.
    """
    kind = type(value)
    if value is None or kind is bool or kind is str:
        return
    if kind is int:
        return
    if kind is float:
        if not math.isfinite(value):
            raise ValueError("payload numbers must be finite")
        return
    if kind is list:
        for item in value:
            _validate_payload(item)
        return
    if kind is dict:
        for key, item in value.items():
            if type(key) is not str:
                raise ValueError("payload object keys must be strings")
            _validate_payload(item)
        return
    raise ValueError("payload contains a value that is not valid JSON")


def _canonical(payload):
    return json.dumps(
        payload,
        sort_keys=True,
        ensure_ascii=False,
        separators=(",", ":"),
        allow_nan=False,
    )


class Inbox:
    def __init__(self, path):
        self.path = os.fspath(path)
        self._records = []
        self._load()

    # -- persistence ------------------------------------------------------
    def _load(self):
        if not os.path.exists(self.path):
            self._records = []
            return
        with open(self.path, "r", encoding="utf-8") as handle:
            raw = handle.read()
        try:
            document = json.loads(raw)
        except ValueError:
            raise ValueError("malformed inbox document")
        self._records = self._validate_document(document)
        if any(record["status"] == "running" for record in self._records):
            recovered = copy.deepcopy(self._records)
            for record in recovered:
                if record["status"] == "running":
                    record["status"] = "interrupted"
            self._save(recovered)
            self._records = recovered

    def _save(self, records):
        document = {"version": 1, "records": records}
        target = self.path
        parent = os.path.dirname(os.path.abspath(target))
        os.makedirs(parent, exist_ok=True)
        descriptor, temporary = tempfile.mkstemp(
            prefix=".inbox-", suffix=".tmp", dir=parent
        )
        try:
            with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
                json.dump(
                    document,
                    handle,
                    ensure_ascii=False,
                    separators=(",", ":"),
                    allow_nan=False,
                )
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, target)
        except OSError:
            try:
                os.unlink(temporary)
            except OSError:
                pass
            raise

    # -- validation -------------------------------------------------------
    def _validate_document(self, document):
        if type(document) is not dict:
            raise ValueError("document must be a JSON object")
        if frozenset(document.keys()) != _DOCUMENT_KEYS:
            raise ValueError("invalid document schema")
        version = document["version"]
        if type(version) is not int or version != 1:
            raise ValueError("unsupported document version")
        records = document["records"]
        if type(records) is not list:
            raise ValueError("records must be a list")
        validated = []
        seen = set()
        for record in records:
            validated.append(self._validate_record(record, seen))
        return validated

    def _validate_record(self, record, seen):
        if type(record) is not dict:
            raise ValueError("record must be a JSON object")
        if frozenset(record.keys()) != _RECORD_KEYS:
            raise ValueError("invalid record schema")
        identifier = record["id"]
        _validate_id(identifier)
        if identifier in seen:
            raise ValueError("duplicate record id")
        seen.add(identifier)
        status = record["status"]
        if status not in VALID_STATUSES:
            raise ValueError("invalid record status")
        payload = record["payload"]
        _validate_payload(payload)
        return {
            "id": identifier,
            "payload": copy.deepcopy(payload),
            "status": status,
        }

    # -- public API -------------------------------------------------------
    def submit(self, identifier, payload):
        _validate_id(identifier)
        _validate_payload(payload)
        for record in self._records:
            if record["id"] == identifier:
                if _canonical(record["payload"]) == _canonical(payload):
                    return copy.deepcopy(record)
                raise ValueError("conflicting duplicate id")
        new_record = {
            "id": identifier,
            "payload": copy.deepcopy(payload),
            "status": "pending",
        }
        candidate = copy.deepcopy(self._records)
        candidate.append(new_record)
        self._save(candidate)
        self._records = candidate
        return copy.deepcopy(new_record)

    def start_next(self):
        for record in self._records:
            if record["status"] == "running":
                raise RuntimeError("a record is already running")
        for index, record in enumerate(self._records):
            if record["status"] == "pending":
                candidate = copy.deepcopy(self._records)
                candidate[index]["status"] = "running"
                self._save(candidate)
                self._records = candidate
                return copy.deepcopy(candidate[index])
        return None

    def finish(self, identifier):
        for record in self._records:
            if record["id"] == identifier:
                status = record["status"]
                if status == "completed":
                    return copy.deepcopy(record)
                if status != "running":
                    raise ValueError("record is not running")
                candidate = copy.deepcopy(self._records)
                for item in candidate:
                    if item["id"] == identifier:
                        item["status"] = "completed"
                        break
                self._save(candidate)
                self._records = candidate
                return copy.deepcopy(
                    next(item for item in candidate if item["id"] == identifier)
                )
        raise KeyError(identifier)

    def snapshot(self):
        return copy.deepcopy(self._records)

