"""Customer total reporting.

Like :mod:`checkout`, this module shapes results only and delegates all money
math to :func:`pricing.price_line`, looked up on the module at call time.
"""

from decimal import Decimal, ROUND_HALF_UP

import pricing

REPORT_FORMAT = 'customer-totals-v1'

_QUANTUM = Decimal("0.01")


def _format(amount):
    """Render a numeric amount as a fixed 2-decimal string."""
    return str(Decimal(amount).quantize(_QUANTUM, rounding=ROUND_HALF_UP))


def customer_totals(orders):
    """Aggregate rounded line amounts per customer, sorted by customer."""
    totals = {}
    for order in orders:
        tier = order.get('tier', 'bronze')
        pricing.validate_tier(tier)
        amount = Decimal("0.00")
        for item in order['items']:
            amount += pricing.price_line(item['unit_price'], item['quantity'], tier)
        customer = order['customer']
        totals[customer] = totals.get(customer, Decimal("0.00")) + amount
    return [
        {'customer': customer, 'total': _format(total)}
        for customer, total in sorted(totals.items())
    ]

files.inbox.py:
"""Recoverable idempotent inbox persisted as a single JSON document.

The public surface is :class:`Inbox`.  Every mutating method writes the whole
document to a temporary file in the destination directory, flushes and fsyncs
it, and only then atomically replaces the destination with ``os.replace``.
In-memory state is swapped in only after the save succeeded, so a failing save
propagates the ``OSError`` and leaves the inbox exactly as it was.
"""

from __future__ import annotations

import json
import math
import os
import tempfile

__all__ = ["Inbox"]

_VERSION = 1
_STATUSES = frozenset({"pending", "running", "completed", "interrupted"})
_PENDING = "pending"
_RUNNING = "running"
_COMPLETED = "completed"
_INTERRUPTED = "interrupted"

_MAX_ID_LENGTH = 64
_MAX_PAYLOAD_DEPTH = 200

# Canonical form used to decide whether two payloads are "identical".
_CANONICAL_KWARGS = {
    "sort_keys": True,
    "ensure_ascii": False,
    "separators": (",", ":"),
    "allow_nan": False,
}
# Same encoding, but keeping the caller's object key order for stored payloads.
_STORAGE_KWARGS = {
    "ensure_ascii": False,
    "separators": (",", ":"),
    "allow_nan": False,
}


def _validate_identifier(identifier):
    """Return *identifier* if it is a valid record id, else raise ValueError."""
    if not isinstance(identifier, str):
        raise ValueError(
            "id must be a string, got %s" % type(identifier).__name__
        )
    if not identifier:
        raise ValueError("id must not be empty")
    if len(identifier) > _MAX_ID_LENGTH:
        raise ValueError(
            "id must be at most %d characters, got %d"
            % (_MAX_ID_LENGTH, len(identifier))
        )
    return identifier


def _validate_payload(payload, depth=0):
    """Raise ValueError unless *payload* is a JSON value as documented."""
    if depth > _MAX_PAYLOAD_DEPTH:
        raise ValueError("payload is nested too deeply")
    if payload is None or isinstance(payload, bool):
        return
    if isinstance(payload, str):
        return
    if isinstance(payload, int):
        return
    if isinstance(payload, float):
        if not math.isfinite(payload):
            raise ValueError("payload numbers must be finite")
        return
    if isinstance(payload, list):
        for item in payload:
            _validate_payload(item, depth + 1)
        return
    if isinstance(payload, dict):
        for key, item in payload.items():
            if not isinstance(key, str):
                raise ValueError("payload object keys must be strings")
            _validate_payload(item, depth + 1)
        return
    raise ValueError(
        "payload must be JSON, got %s" % type(payload).__name__
    )


def _detach(value):
    """Deep copy a validated payload so callers can never alias stored state."""
    if isinstance(value, dict):
        return {key: _detach(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_detach(item) for item in value]
    return value


def _canonical(payload):
    return json.dumps(payload, **_CANONICAL_KWARGS)


def _make_record(identifier, payload, status):
    return {"id": identifier, "payload": payload, "status": status}


def _detach_record(record):
    return _make_record(
        record["id"], _detach(record["payload"]), record["status"]
    )


def _decode_record(raw):
    if not isinstance(raw, dict):
        raise ValueError("each record must be a JSON object")
    if set(raw) != {"id", "payload", "status"}:
        raise ValueError(
            "each record must have exactly the fields id, payload and status"
        )
    identifier = _validate_identifier(raw["id"])
    status = raw["status"]
    if not isinstance(status, str) or status not in _STATUSES:
        raise ValueError("invalid record status: %r" % (status,))
    payload = raw["payload"]
    _validate_payload(payload)
    return _make_record(identifier, payload, status)


def _decode_document(document):
    if not isinstance(document, dict):
        raise ValueError("inbox document must be a JSON object")
    if set(document) != {"version", "records"}:
        raise ValueError(
            "inbox document must have exactly the keys 'version' and 'records'"
        )
    version = document["version"]
    if type(version) is not int or version != _VERSION:
        raise ValueError("unsupported inbox version: %r" % (version,))
    raw_records = document["records"]
    if not isinstance(raw_records, list):
        raise ValueError("inbox 'records' must be a JSON array")
    records = []
    seen = set()
    for raw in raw_records:
        record = _decode_record(raw)
        if record["id"] in seen:
            raise ValueError("duplicate record id: %r" % (record["id"],))
        seen.add(record["id"])
        records.append(record)
    return records


class Inbox:
    """A single-process, single-writer, durably persisted JSON inbox."""

    def __init__(self, path):
        self.path = path
        self._records = self._load()
        # Recovery: a record left "running" by a previous process can never be
        # acknowledged again, so it becomes "interrupted" and that recovery is
        # persisted before this instance is handed back to the caller.
        if any(record["status"] == _RUNNING for record in self._records):
            recovered = [
                _make_record(
                    record["id"],
                    record["payload"],
                    _INTERRUPTED
                    if record["status"] == _RUNNING
                    else record["status"],
                )
                for record in self._records
            ]
            self._save(recovered)
            self._records = recovered

    # ------------------------------------------------------------------ API
    def submit(self, identifier, payload):
        """Add a pending record, or return the existing identical one."""
        _validate_identifier(identifier)
        _validate_payload(payload)
        for record in self._records:
            if record["id"] == identifier:
                if _canonical(record["payload"]) == _canonical(payload):
                    return _detach_record(record)
                raise ValueError(
                    "id %r already exists with a different payload"
                    % (identifier,)
                )
        record = _make_record(identifier, _detach(payload), _PENDING)
        records = self._records + [record]
        self._save(records)
        self._records = records
        return _detach_record(record)

    def start_next(self):
        """Mark the first pending record running and return a detached copy."""
        for record in self._records:
            if record["status"] == _RUNNING:
                raise RuntimeError(
                    "record %r is already running" % (record["id"],)
                )
        for index, record in enumerate(self._records):
            if record["status"] == _PENDING:
                started = _make_record(
                    record["id"], record["payload"], _RUNNING
                )
                records = list(self._records)
                records[index] = started
                self._save(records)
                self._records = records
                return _detach_record(started)
        return None

    def finish(self, identifier):
        """Mark a running record completed and return a detached copy."""
        index = None
        for position, record in enumerate(self._records):
            if record["id"] == identifier:
                index = position
                break
        if index is None:
            raise KeyError(identifier)
        current = self._records[index]
        if current["status"] == _COMPLETED:
            return _detach_record(current)
        if current["status"] != _RUNNING:
            raise ValueError(
                "record %r is not running (status=%s)"
                % (identifier, current["status"])
            )
        finished = _make_record(current["id"], current["payload"], _COMPLETED)
        records = list(self._records)
        records[index] = finished
        self._save(records)
        self._records = records
        return _detach_record(finished)

    def snapshot(self):
        """Return a detached deep copy of all records, in submission order."""
        return [_detach_record(record) for record in self._records]

    # ------------------------------------------------------------- internals
    def _load(self):
        path = os.fspath(self.path)
        try:
            with open(path, "r", encoding="utf-8") as handle:
                text = handle.read()
        except FileNotFoundError:
            return []
        try:
            document = json.loads(text)
        except ValueError as exc:
            raise ValueError("inbox file is not valid JSON: %s" % (exc,))
        return _decode_document(document)

    def _save(self, records):
        """Durably persist *records*; the caller swaps state only on success."""
        document = {"version": _VERSION, "records": records}
        data = json.dumps(document, **_STORAGE_KWARGS)
        path = os.path.abspath(os.fspath(self.path))
        directory = os.path.dirname(path) or os.curdir
        os.makedirs(directory, exist_ok=True)
        handle_fd, temp_path = tempfile.mkstemp(
            dir=directory,
            prefix=os.path.basename(path) + ".",
            suffix=".tmp",
        )
        try:
            with os.fdopen(handle_fd, "w", encoding="utf-8", newline="") as out:
                out.write(data)
                out.flush()
                os.fsync(out.fileno())
            os.replace(temp_path, path)
        except BaseException:
            try:
                os.remove(temp_path)
            except OSError:
                pass
            raise

