def _as_int(value, name):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError("%s must be an integer" % name)
    return value


def coverage(intervals, start, end):
    start = _as_int(start, "start")
    end = _as_int(end, "end")
    if start > end:
        raise ValueError("start must be <= end")

    try:
        iterator = iter(intervals)
    except TypeError:
        raise ValueError("intervals must be a finite iterable") from None

    raw = []
    for item in iterator:
        if not isinstance(item, (list, tuple)):
            raise ValueError("each interval must be a two-element list or tuple")
        if len(item) != 2:
            raise ValueError("each interval must have exactly two elements")
        lo = _as_int(item[0], "interval lower bound")
        hi = _as_int(item[1], "interval upper bound")
        if lo > hi:
            raise ValueError("interval lower bound must be <= upper bound")
        raw.append((lo, hi))

    merged = []
    if start != end:
        clipped = []
        for lo, hi in raw:
            c_lo = lo if lo > start else start
            c_hi = hi if hi < end else end
            if c_lo < c_hi:
                clipped.append((c_lo, c_hi))
        clipped.sort()
        for lo, hi in clipped:
            if merged and lo <= merged[-1][1]:
                if hi > merged[-1][1]:
                    merged[-1][1] = hi
            else:
                merged.append([lo, hi])

    gaps = []
    if start != end:
        prev = start
        for lo, hi in merged:
            if lo > prev:
                gaps.append([prev, lo])
            prev = hi
        if prev < end:
            gaps.append([prev, end])

    covered = 0
    for lo, hi in merged:
        covered += hi - lo

    return {"merged": merged, "gaps": gaps, "covered": covered}

