import re

_PARAM_RE = re.compile(r"^:[A-Za-z_][A-Za-z0-9_]*$")


def _collapse(path):
    while "//" in path:
        path = path.replace("//", "/")
    if len(path) > 1:
        path = path.rstrip("/")
        if path == "":
            path = "/"
    return path


def _split(path):
    if path == "/":
        return []
    return path[1:].split("/")


def _discard_query(path):
    cut = len(path)
    for ch in ("?", "#"):
        idx = path.find(ch)
        if idx != -1 and idx < cut:
            cut = idx
    return path[:cut]


def _parse_pattern(pattern):
    if not isinstance(pattern, str):
        raise ValueError("pattern must be a string")
    if not pattern.startswith("/"):
        raise ValueError("pattern must start with '/'")
    if "?" in pattern or "#" in pattern:
        raise ValueError("pattern may not contain '?' or '#'")

    normalized = _collapse(pattern)
    seen = set()
    parsed = []
    for segment in _split(normalized):
        if segment.startswith(":"):
            if not _PARAM_RE.match(segment):
                raise ValueError("invalid parameter segment: %r" % segment)
            name = segment[1:]
            if name in seen:
                raise ValueError("duplicate parameter name: %r" % name)
            seen.add(name)
            parsed.append((True, name))
        else:
            parsed.append((False, segment))
    return normalized, parsed


class Router:
    def __init__(self):
        self.routes = []

    def add(self, pattern, handler):
        normalized, parsed = _parse_pattern(pattern)
        for index, (key, _segments, _handler) in enumerate(self.routes):
            if key == normalized:
                self.routes[index] = (key, parsed, handler)
                return
        self.routes.append((normalized, parsed, handler))

    def resolve(self, path):
        if not isinstance(path, str):
            raise ValueError("path must be a string")
        if not path.startswith("/"):
            raise ValueError("path must start with '/'")

        normalized = _collapse(_discard_query(path))
        segments = _split(normalized)

        best_handler = None
        best_params = None
        best_static = -1

        for _key, parsed, handler in self.routes:
            if len(parsed) != len(segments):
                continue
            params = {}
            static_count = 0
            matched = True
            for (is_param, value), actual in zip(parsed, segments):
                if is_param:
                    if actual == "":
                        matched = False
                        break
                    params[value] = actual
                else:
                    static_count += 1
                    if value != actual:
                        matched = False
                        break
            if not matched:
                continue
            if static_count > best_static:
                best_static = static_count
                best_handler = handler
                best_params = params

        if best_handler is None:
            raise KeyError(path)
        return best_handler, best_params

