"""Command line interface: ``python -m receipt_tools.cli INPUT.jsonl OUTPUT.csv``."""

import argparse
import csv
import io
import json
import os
import sys
import tempfile

from .model import summarize

__all__ = ["main"]


def _read_records(path):
    with open(path, "r", encoding="utf-8", newline="") as handle:
        for line in handle:
            if line.strip() == "":
                continue
            yield json.loads(line)


def _render(summary):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["customer", "count", "total"])
    for row in summary:
        writer.writerow([row["customer"], row["count"], row["total"]])
    return buffer.getvalue()


def _write_atomic(path, text):
    directory = os.path.dirname(os.path.abspath(path))
    os.makedirs(directory, exist_ok=True)
    handle, tmp_path = tempfile.mkstemp(dir=directory, prefix=".receipt_", suffix=".tmp")
    try:
        with os.fdopen(handle, "w", encoding="utf-8", newline="") as stream:
            stream.write(text)
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.remove(tmp_path)
        except OSError:
            pass
        raise


def main(argv=None):
    parser = argparse.ArgumentParser(prog="receipt_tools.cli")
    parser.add_argument("input")
    parser.add_argument("output")
    args = parser.parse_args(argv)

    try:
        summary = summarize(_read_records(args.input))
    except (OSError, ValueError) as exc:
        print("error: %s" % exc, file=sys.stderr)
        return 1

    try:
        _write_atomic(args.output, _render(summary))
    except OSError as exc:
        print("error: %s" % exc, file=sys.stderr)
        return 1

    return 0


if __name__ == "__main__":
    sys.exit(main())

