"""Core receipt summarization logic."""

import re
from decimal import Decimal, ROUND_HALF_UP, localcontext

__all__ = ["summarize"]

_AMOUNT_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?")
_TWO_PLACES = Decimal("0.01")
_REQUIRED_FIELDS = ("customer", "amount", "status")


def _fail(message):
    raise ValueError(message)


def summarize(records):
    """Summarize receipt records.

    Returns a list of ``{"customer": str, "count": int, "total": str}`` dicts
    sorted by customer, combining equal (stripped) customer names.  Only rows
    whose status is ``"paid"`` contribute.  Every row is validated first; any
    missing or invalid field raises :class:`ValueError`.
    """
    grouped = {}
    counts = {}

    with localcontext() as ctx:
        ctx.prec = 1000
        for record in records:
            if not isinstance(record, dict):
                _fail("receipt must be a mapping")

            for field in _REQUIRED_FIELDS:
                if field not in record:
                    _fail("missing field: %s" % field)

            customer = record["customer"]
            amount = record["amount"]
            status = record["status"]

            if not isinstance(customer, str):
                _fail("customer must be a string")
            customer = customer.strip()
            if not customer:
                _fail("customer must be a nonempty string")

            if not isinstance(amount, str) or _AMOUNT_RE.fullmatch(amount) is None:
                _fail("invalid amount: %r" % (amount,))

            if status != "paid" and status != "void":
                _fail("invalid status: %r" % (status,))

            if status == "void":
                continue

            value = Decimal(amount)
            if customer in grouped:
                grouped[customer] += value
                counts[customer] += 1
            else:
                grouped[customer] = value
                counts[customer] = 1

        result = []
        for customer in sorted(grouped):
            total = grouped[customer].quantize(_TWO_PLACES, rounding=ROUND_HALF_UP)
            result.append(
                {
                    "customer": customer,
                    "count": counts[customer],
                    "total": format(total, "f"),
                }
            )

    return result

files.coverage.py:
"""Normalize half-open interval coverage.

Public API:
    coverage(intervals, start, end) -> {'merged': [...], 'gaps': [...], 'covered': int}

See README.md for the full contract.
"""


def _is_int(value):
    """Return True for genuine integers, rejecting bool (a subclass of int)."""
    return isinstance(value, int) and not isinstance(value, bool)


def coverage(intervals, start, end):
    """Clip, merge and complement half-open intervals within [start, end).

    Treats every input interval as half-open ``[lo, hi)``, clips it to the
    requested window ``[start, end)``, drops empty results, then sorts and
    merges overlapping or touching intervals.  Returns the merged intervals,
    the sorted nonempty gaps (complement within the window) and the total
    covered integer length.

    Raises ``ValueError`` for any invalid input, including invalid intervals
    that lie wholly outside the requested window.
    """
    # --- validate the window -------------------------------------------------
    if not _is_int(start) or not _is_int(end):
        raise ValueError("start and end must be integers")
    if start > end:
        raise ValueError("start must be less than or equal to end")

    # --- obtain and validate the iterable ------------------------------------
    try:
        iterator = iter(intervals)
    except TypeError:
        raise ValueError("intervals must be a finite iterable") from None

    clipped = []
    for item in iterator:
        if not isinstance(item, (list, tuple)):
            raise ValueError("each interval must be a list or tuple")
        if len(item) != 2:
            raise ValueError("each interval must have exactly two elements")

        lo, hi = item[0], item[1]
        if not _is_int(lo) or not _is_int(hi):
            raise ValueError("interval endpoints must be integers")
        if lo > hi:
            raise ValueError("interval lo must be less than or equal to hi")

        # Clip to [start, end).  Validity is checked above regardless of
        # whether the interval survives clipping.
        clo = lo if lo > start else start
        chi = hi if hi < end else end
        if clo < chi:
            clipped.append((clo, chi))

    # Empty window: nothing can be covered and there are no gaps.
    if start == end:
        return {"merged": [], "gaps": [], "covered": 0}

    # --- merge ---------------------------------------------------------------
    clipped.sort()
    merged = []
    for lo, hi in clipped:
        if merged and lo <= merged[-1][1]:
            # Overlapping or touching: extend the current interval.
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    # --- complement ----------------------------------------------------------
    gaps = []
    cursor = start
    for lo, hi in merged:
        if lo > cursor:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    covered = sum(hi - lo for lo, hi in merged)
    return {"merged": merged, "gaps": gaps, "covered": covered}

