import unittest

from coverage import coverage


class BasicContract(unittest.TestCase):
    def test_public_smoke(self):
        self.assertEqual(
            coverage([[3, 5], [-2, 2], [2, 4]], 0, 7),
            {"merged": [[0, 5]], "gaps": [[5, 7]], "covered": 5},
        )

    def test_empty_intervals(self):
        self.assertEqual(
            coverage([], 0, 5),
            {"merged": [], "gaps": [[0, 5]], "covered": 0},
        )

    def test_empty_window(self):
        self.assertEqual(
            coverage([[0, 10]], 3, 3),
            {"merged": [], "gaps": [], "covered": 0},
        )

    def test_empty_window_invalid_still_raises(self):
