def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def coverage(intervals, start, end):
    if not _is_int(start) or not _is_int(end):
        raise ValueError("start and end must be integers")
    if start > end:
        raise ValueError("start must be less than or equal to end")

    try:
        iterator = iter(intervals)
    except TypeError:
        raise ValueError("intervals must be an iterable of [lo, hi] pairs")

    clipped = []
    for item in iterator:
        if not isinstance(item, (list, tuple)):
            raise ValueError("each interval must be a list or tuple")
        if len(item) != 2:
            raise ValueError("each interval must contain exactly two endpoints")
        lo, hi = item
        if not _is_int(lo) or not _is_int(hi):
            raise ValueError("interval endpoints must be integers")
        if lo > hi:
            raise ValueError("interval lower bound must be <= upper bound")

        clipped_lo = lo if lo > start else start
        clipped_hi = hi if hi < end else end
        if clipped_lo < clipped_hi:
            clipped.append((clipped_lo, clipped_hi))

    clipped.sort()

    merged = []
    for lo, hi in clipped:
        if merged and lo <= merged[-1][1]:
            if hi > merged[-1][1]:
                merged[-1] = (merged[-1][0], hi)
        else:
            merged.append((lo, hi))

    gaps = []
    cursor = start
    for lo, hi in merged:
        if lo > cursor:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    merged_out = []
    covered = 0
    for lo, hi in merged:
        merged_out.append([lo, hi])
        covered += hi - lo

    return {"merged": merged_out, "gaps": gaps, "covered": covered}

