"""A tiny path router.

Public API (unchanged):

    Router()
    Router.add(pattern, handler)   -> None
    Router.resolve(path)           -> (handler, params_dict)

See README.md for the full contract.
"""

import re

# A parameter is a whole segment of the form ":name" where name is an ASCII
# identifier.  ``fullmatch`` guarantees the entire segment is consumed.
_PARAM_RE = re.compile(r":[A-Za-z_][A-Za-z0-9_]*")


def _split(path):
    """Split a normalized-looking path into nonempty segments.

    Dropping empty segments collapses repeated ``/`` and ignores any leading
    or trailing ``/`` (a bare root yields ``[]``).
    """
    return [segment for segment in path.split("/") if segment != ""]


def _normalize(pattern):
    """Return the canonical form of a path/pattern (slash normalization)."""
    segments = _split(pattern)
    if not segments:
        return "/"
    return "/" + "/".join(segments)


def _parse_pattern(normalized):
    """Turn a normalized pattern into (tokens, static_count).

    tokens is a list of (is_static, value).  Raises ValueError for malformed
    parameter segments or duplicate parameter names.
    """
    tokens = []
    seen = set()
    static_count = 0
    for segment in _split(normalized):
        if segment.startswith(":"):
            if _PARAM_RE.fullmatch(segment) is None:
                raise ValueError("invalid parameter segment: %r" % (segment,))
            name = segment[1:]
            if name in seen:
                raise ValueError("duplicate parameter name: %r" % (name,))
            seen.add(name)
            tokens.append((False, name))
        else:
            tokens.append((True, segment))
            static_count += 1
    return tokens, static_count


class Router:
    def __init__(self):
        # Each entry: [normalized_pattern, tokens, static_count, handler]
        self.routes = []

    def add(self, pattern, handler):
        if not isinstance(pattern, str) or not pattern.startswith("/"):
            raise ValueError("pattern must be a string starting with '/': %r"
                             % (pattern,))
        if "?" in pattern or "#" in pattern:
            raise ValueError("pattern may not contain '?' or '#': %r"
                             % (pattern,))

        # Validate fully *before* touching self.routes so that a failed add
        # leaves every registered route untouched.
        normalized = _normalize(pattern)
        tokens, static_count = _parse_pattern(normalized)

        for entry in self.routes:
            if entry[0] == normalized:
                # Same normalized pattern: replace the handler, keep order.
                entry[1] = tokens
                entry[2] = static_count
                entry[3] = handler
                return

        self.routes.append([normalized, tokens, static_count, handler])

    def resolve(self, path):
        if not isinstance(path, str) or not path.startswith("/"):
            raise ValueError("path must be a string starting with '/': %r"
                             % (path,))

        original = path

        # On resolve only, discard the first '?' or '#' and everything after.
        cut = len(path)
        for marker in ("?", "#"):
            pos = path.find(marker)
            if pos != -1 and pos < cut:
                cut = pos
        if cut != len(path):
            path = path[:cut]

        parts = _split(path)

        best_handler = None
        best_params = None
        best_static = -1
        found = False

        for _normalized, tokens, static_count, handler in self.routes:
            if len(tokens) != len(parts):
                continue
            params = {}
            for (is_static, value), actual in zip(tokens, parts):
                if is_static:
                    if value != actual:
                        break
                else:
                    params[value] = actual
            else:
                # A match: prefer the route with the most static segments;
                # strict '>' keeps the earliest registration on ties.
                if not found or static_count > best_static:
                    found = True
                    best_static = static_count
                    best_handler = handler
                    best_params = params

        if not found:
            raise KeyError(original)
        return best_handler, best_params

