"""Normalize half-open interval coverage.

See README.md for the public contract.
"""

__all__ = ["coverage"]


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def coverage(intervals, start, end):
    """Clip, merge and summarize half-open integer intervals.

    Parameters
    ----------
    intervals:
        Any finite iterable of two-element lists/tuples ``[lo, hi]``.
    start, end:
        Integer window bounds with ``start <= end``.

    Returns
    -------
    dict
        ``{'merged': [[lo, hi], ...], 'gaps': [[lo, hi], ...],
        'covered': int}``
    """
    # --- Validate the window bounds -------------------------------------
    if not _is_int(start) or not _is_int(end):
        raise ValueError("start and end must be integers (bool is invalid)")
    if start > end:
        raise ValueError("start must be <= end")

    # --- Validate and collect the input intervals -----------------------
    try:
        iterator = iter(intervals)
    except TypeError:
        raise ValueError("intervals must be a finite iterable")

    collected = []
    for item in iterator:
        if not isinstance(item, (list, tuple)):
            raise ValueError("each interval must be a list or tuple")
        if len(item) != 2:
            raise ValueError("each interval must have exactly two elements")
        lo, hi = item[0], item[1]
        if not _is_int(lo) or not _is_int(hi):
            raise ValueError("interval endpoints must be integers (bool is invalid)")
        if lo > hi:
            raise ValueError("interval endpoints must satisfy lo <= hi")
        # Copy into a plain tuple so caller data is never mutated or aliased.
        collected.append((lo, hi))

    # --- Empty window ----------------------------------------------------
    if start == end:
        return {"merged": [], "gaps": [], "covered": 0}

    # --- Clip each interval to the window, dropping empty ones -----------
    clipped = []
    for lo, hi in collected:
        clo = lo if lo > start else start
        chi = hi if hi < end else end
        if clo < chi:
            clipped.append((clo, chi))

    # --- Sort and merge overlapping OR touching intervals ----------------
    clipped.sort()
    merged = []
    for lo, hi in clipped:
        if merged and lo <= merged[-1][1]:
            # Overlapping or touching: extend the previous interval.
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    # --- Build the complement (gaps) within [start, end) -----------------
    gaps = []
    cursor = start
    for lo, hi in merged:
        if cursor < lo:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    covered = sum(hi - lo for lo, hi in merged)

    return {"merged": merged, "gaps": gaps, "covered": covered}

