import re
from decimal import Decimal, ROUND_HALF_UP

__all__ = ["summarize"]

_AMOUNT_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?\Z")


def _validate(record):
    if not isinstance(record, dict):
        raise ValueError("receipt must be a mapping")

    customer = record.get("customer")
    if not isinstance(customer, str) or not customer.strip():
        raise ValueError("invalid customer")

    amount = record.get("amount")
    if not isinstance(amount, str) or not _AMOUNT_RE.match(amount):
        raise ValueError("invalid amount")

    status = record.get("status")
    if status != "paid" and status != "void":
        raise ValueError("invalid status")

    return customer.strip(), amount, status


def summarize(records):
    """Summarize an iterable of receipt dicts.

    Returns a list of ``{customer, count, total}`` sorted by customer.
    """
    totals = {}
    counts = {}
    for record in records:
        customer, amount, status = _validate(record)
        if status == "paid":
            totals[customer] = totals.get(customer, Decimal(0)) + Decimal(amount)
            counts[customer] = counts.get(customer, 0) + 1

    result = []
    for customer in sorted(totals):
        total = totals[customer].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        result.append(
            {"customer": customer, "count": counts[customer], "total": str(total)}
        )
    return result

