"""Extra checks for the coverage() contract (beyond public_tests.py)."""

import os
import random
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from coverage import coverage


def brute_force(intervals, start, end):
    """Reference implementation by literal enumeration of a small window."""
    covered_set = set()
    for lo, hi in intervals:
        for x in range(max(lo, start), min(hi, end)):
            covered_set.add(x)
    bits = [x in covered_set for x in range(start, end)]

    def runs(target):
        out = []
        i = 0
        while i < len(bits):
            if bits[i] is target:
                j = i
                while j < len(bits) and bits[j] is target:
                    j += 1
                out.append([start + i, start + j])
                i = j
            else:
                i += 1
        return out

    return {
        "merged": runs(True),
        "gaps": runs(False),
        "covered": sum(bits),
    }


class TestBasics(unittest.TestCase):
    def test_smoke_case(self):
        self.assertEqual(
            coverage([[3, 5], [-2, 2], [2, 4]], 0, 7),
            {"merged": [[0, 5]], "gaps": [[5, 7]], "covered": 5},
        )

    def test_keys_and_types_are_exact(self):
        result = coverage([[1, 3]], 0, 5)
        self.assertEqual(set(result), {"merged", "gaps", "covered"})
        self.assertIsInstance(result["merged"], list)
        self.assertIsInstance(result["gaps"], list)
        self.assertIsInstance(result["covered"], int)
        for part in result["merged"] + result["gaps"]:
            self.assertIsInstance(part, list)
            self.assertEqual(len(part), 2)
            self.assertTrue(all(isinstance(v, int) for v in part))

    def test_empty_window(self):
        self.assertEqual(
            coverage([[-5, 5], [0, 0]], 3, 3),
            {"merged": [], "gaps": [], "covered": 0},
        )

    def test_empty_intervals(self):
        self.assertEqual(
            coverage([], 2, 5),
            {"merged": [], "gaps": [[2, 5]], "covered": 0},
        )

    def test_unsorted_input(self):
        self.assertEqual(
            coverage([[4, 6], [0, 2]], 0, 8),
            {"merged": [[0, 2], [4, 6]], "gaps": [[2, 4], [6, 8]], "covered": 4},
        )

    def test_touching_intervals_merge(self):
        self.assertEqual(
            coverage([[0, 2], [2, 4], [4, 4]], 0, 4),
            {"merged": [[0, 4]], "gaps": [], "covered": 4},
        )

    def test_duplicates_and_nesting(self):
        self.assertEqual(
            coverage([[1, 5], [1, 5], [2, 3], [3, 4]], 0, 6),
            {"merged": [[1, 5]], "gaps": [[0, 1], [5, 6]], "covered": 4},
        )

    def test_window_inside_single_interval(self):
        self.assertEqual(
            coverage([[-10, 10]], -3, 3),
            {"merged": [[-3, 3]], "gaps": [], "covered": 6},
        )

    def test_zero_length_interval_ignored(self):
        self.assertEqual(
            coverage([[2, 2], [4, 4]], 0, 6),
            {"merged": [], "gaps": [[0, 6]], "covered": 0},
        )

    def test_wholly_outside_intervals_are_ignored_when_valid(self):
        self.assertEqual(
            coverage([[-9, -5], [40, 50], [0, 1]], 0, 3),
            {"merged": [[0, 1]], "gaps": [[1, 3]], "covered": 1},
        )


class TestBigIntegers(unittest.TestCase):
    def test_huge_bounds(self):
        big = 10 ** 40
        result = coverage([[big, big + 5]], -big, 2 * big)
        self.assertEqual(result["covered"], 5)
        self.assertEqual(result["merged"], [[big, big + 5]])
        self.assertEqual(result["gaps"], [[-big, big], [big + 5, 2 * big]])
        # covered + gap lengths must span the whole window
        total = result["covered"] + sum(hi - lo for lo, hi in result["gaps"])
        self.assertEqual(total, 3 * big)
        # an interval starting exactly at `end` clips away to nothing
        self.assertEqual(
            coverage([[big, big + 5]], -big, big),
            {"merged": [], "gaps": [[-big, big]], "covered": 0},
        )

    def test_deep_negative_window(self):
        self.assertEqual(
            coverage([[-10 ** 30, -10 ** 30 + 3], [-1, 1]], -10 ** 30, 2),
            {
                "merged": [[-10 ** 30, -10 ** 30 + 3], [-1, 1]],
                "gaps": [[-10 ** 30 + 3, -1], [1, 2]],
                "covered": 5,
