    def test_item_shape_invalid(self):
        self.assert_invalid([[0, 1, 2]], 0, 3)
        self.assert_invalid([[0]], 0, 3)
        self.assert_invalid([[]], 0, 3)
        self.assert_invalid([0], 0, 3)
        self.assert_invalid(["ab"], 0, 3)
        self.assert_invalid([{0, 1}], 0, 3)
        self.assert_invalid([3, [0, 1]], 0, 3)

    def test_non_integer_endpoints(self):
        self.assert_invalid([[0.5, 2]], 0, 3)
        self.assert_invalid([[0, "2"]], 0, 3)
        self.assert_invalid([[None, 2]], 0, 3)

    def test_bool_endpoints_rejected(self):
        self.assert_invalid([[True, 2]], 0, 3)
        self.assert_invalid([[0, False]], 0, 3)

    def test_reversed_interval_inside_window(self):
        self.assert_invalid([[3, 1]], 0, 5)

    def test_reversed_interval_wholly_outside_window(self):
        self.assert_invalid([[10 ** 9, 10 ** 9 - 1]], 0, 5)
        self.assert_invalid([[-50, -60]], 0, 5)
        self.assert_invalid([[3, 1], [0, 5]], 0, 5)

    def test_non_integer_endpoint_wholly_outside_window(self):
        self.assert_invalid([[100.5, 200]], 0, 5)

    def test_later_invalid_item_after_valid_ones(self):
        self.assert_invalid([[0, 1], [2, 2], [7, 6]], 0, 9)


class TestRandomAgainstBruteForce(unittest.TestCase):
    def test_randomized_cross_check(self):
        rng = random.Random(20260929)
        for _ in range(3000):
            start = rng.randint(-6, 6)
            end = start + rng.randint(0, 6)
            intervals = []
            for _ in range(rng.randint(0, 6)):
                lo = rng.randint(-8, 8)
                hi = rng.randint(lo, 8)
                intervals.append([lo, hi] if rng.random() < 0.5 else (lo, hi))
            expected = brute_force(intervals, start, end)
            got = coverage(intervals, start, end)
            self.assertEqual(got, expected, (intervals, start, end))

    def test_invariants_on_random_valid_input(self):
        rng = random.Random(7)
        for _ in range(500):
            start = rng.randint(-1000, 1000)
            end = start + rng.randint(0, 5000)
            intervals = []
            for _ in range(rng.randint(0, 8)):
                lo = rng.randint(start - 5000, end + 5000)
                hi = rng.randint(lo, end + 5000)
                intervals.append([lo, hi])
            result = coverage(intervals, start, end)
            merged, gaps, covered = result["merged"], result["gaps"], result["covered"]

            # merged is sorted, non-empty, disjoint and non-touching, inside window
            for i, (lo, hi) in enumerate(merged):
                self.assertLess(lo, hi)
                self.assertGreaterEqual(lo, start)
                self.assertLessEqual(hi, end)
                if i:
                    self.assertGreater(lo, merged[i - 1][1])
            # gaps alternate with merged and also stay inside the window
            for lo, hi in gaps:
                self.assertLess(lo, hi)
                self.assertGreaterEqual(lo, start)
                self.assertLessEqual(hi, end)
            self.assertEqual(covered, sum(hi - lo for lo, hi in merged))
            self.assertEqual(
                covered + sum(hi - lo for lo, hi in gaps), end - start
            )
            # merged and gaps interleave and tile the window exactly, in order
            cursor = start
            for lo, hi in sorted(merged + gaps):
                self.assertEqual(lo, cursor, (intervals, start, end, result))
                cursor = hi
            self.assertEqual(cursor, end)
            # merged pieces never touch each other and never outnumber gaps
            # by more than one (boundary-touching coverage explains the rest)
            for i in range(1, len(merged)):
                self.assertGreaterEqual(merged[i][0] - merged[i - 1][1], 2)
            self.assertLessEqual(abs(len(gaps) - len(merged)), 1)
            # cross-check against literal enumeration for small windows
            if end - start <= 400:
                self.assertEqual(
                    result, brute_force(intervals, start, end),
                    (intervals, start, end),
                )


if __name__ == "__main__":
    unittest.main(verbosity=2)

