"""Single owner of the pricing formula shared by checkout and reporting.

Only the Python standard library is used and all money arithmetic is performed
with :class:`decimal.Decimal` so results are exact and rounded exactly once.
"""

import re
from decimal import Decimal, ROUND_HALF_UP, localcontext

CENT = Decimal('0.01')
_MONEY_RE = re.compile(r'[0-9]+(?:\.[0-9]+)?', re.ASCII)
_TIER_FACTORS = {
    'bronze': Decimal('1'),
    'silver': Decimal('0.90'),
    'gold': Decimal('0.80'),
}
BULK_FACTOR = Decimal('0.95')
BULK_MIN_QUANTITY = 10
_PRECISION = 80


def _validate_unit_price(unit_price):
    if not isinstance(unit_price, str):
        raise ValueError('unit_price must be an ASCII decimal string')
    if _MONEY_RE.fullmatch(unit_price) is None:
        raise ValueError('unit_price must match [0-9]+(?:\\.[0-9]+)?')
    return Decimal(unit_price)


def _validate_quantity(quantity):
    if isinstance(quantity, bool) or not isinstance(quantity, int):
        raise ValueError('quantity must be a nonnegative int')
    if quantity < 0:
        raise ValueError('quantity must be nonnegative')
    return quantity


def _validate_tier(tier):
    if not isinstance(tier, str) or tier not in _TIER_FACTORS:
        raise ValueError("tier must be one of 'bronze', 'silver', 'gold'")
    return tier


def price_line(unit_price, quantity, tier='bronze'):
    """Return the discounted, single-rounded line amount as a ``Decimal``.

    The computation is ``unit_price * quantity`` scaled by the tier factor
    (``1`` / ``0.90`` / ``0.80``) and by ``0.95`` when ``quantity >= 10``.
    The final value is quantized to ``0.01`` using ``ROUND_HALF_UP`` exactly
    once. Invalid money, quantity or tier raises :class:`ValueError`.
    """

    price = _validate_unit_price(unit_price)
    qty = _validate_quantity(quantity)
    tier = _validate_tier(tier)

    with localcontext() as ctx:
        ctx.prec = _PRECISION
        value = price * Decimal(qty) * _TIER_FACTORS[tier]
        if qty >= BULK_MIN_QUANTITY:
            value = value * BULK_FACTOR
        return value.quantize(CENT, rounding=ROUND_HALF_UP)


def format_money(value):
    """Render a ``Decimal`` money value as a fixed two-decimal string."""

    return str(Decimal(value).quantize(CENT, rounding=ROUND_HALF_UP))

