from decimal import Decimal

import pricing

REPORT_FORMAT = 'customer-totals-v1'


def customer_totals(orders):
    """Aggregate the same rounded lines across orders, sorted by customer.

    Returns a list of ``{'customer': ..., 'total': '0.00'}`` rows. An order
    with no items still contributes a ``0.00`` row. The caller's dictionaries
    and lists are never mutated.
    """

    totals = {}
    for order in orders:
        customer = order['customer']
        tier = order['tier']
        subtotal = Decimal('0')
        for item in order['items']:
            subtotal += pricing.price_line(item['unit_price'], item['quantity'], tier)
        totals[customer] = totals.get(customer, Decimal('0')) + subtotal
    return [
        {'customer': customer, 'total': pricing.format_money(totals[customer])}
        for customer in sorted(totals)
    ]

