"""Tiny literal path router.

Public API (unchanged):
    Router()
    Router.add(pattern, handler)
    Router.resolve(path) -> (handler, params)

See README.md for the full contract.
"""

import re

# A parameter segment is a colon followed by an ASCII identifier.
_PARAM_RE = re.compile(r":([A-Za-z_][A-Za-z0-9_]*)\Z")


def _is_valid_param(segment):
    """Return the parameter name if *segment* is a valid parameter, else None."""
    match = _PARAM_RE.fullmatch(segment)
    if match is None:
        return None
    return match.group(1)


def _segments(value):
    """Normalize *value* into a tuple of non-empty path segments.

    Repeated ``/`` are collapsed and a trailing ``/`` is ignored, so the root
    path ``/`` becomes the empty tuple ``()``.
    """
    if not isinstance(value, str):
        raise ValueError("path must be a string")
    if not value.startswith("/"):
        raise ValueError("path must start with '/'")
    return tuple(part for part in value.split("/") if part != "")


def _static_count(segments):
    return sum(1 for segment in segments if not segment.startswith(":"))


def _compile_pattern(pattern):
    """Validate and normalize an ``add`` pattern.

    Returns the normalized segment tuple.  Raises ``ValueError`` for any
    invalid pattern without mutating anything.
    """
    if not isinstance(pattern, str):
        raise ValueError("pattern must be a string")
    if not pattern.startswith("/"):
        raise ValueError("pattern must start with '/'")
    if "?" in pattern or "#" in pattern:
        raise ValueError("pattern may not contain '?' or '#'")

    segments = _segments(pattern)
    seen = set()
    for segment in segments:
        if segment.startswith(":"):
            name = _is_valid_param(segment)
            if name is None:
                raise ValueError("invalid parameter segment: %r" % (segment,))
            if name in seen:
                raise ValueError("duplicate parameter name: %r" % (name,))
            seen.add(name)
    return segments


class Router:
    def __init__(self):
        # Each entry: (segments, handler) in registration order.
        self.routes = []

    def add(self, pattern, handler):
        # Validate/normalize first so an invalid pattern changes nothing.
        segments = _compile_pattern(pattern)

        for index, (existing, _handler) in enumerate(self.routes):
            if existing == segments:
                # Same normalized pattern: replace handler, keep order.
                self.routes[index] = (segments, handler)
                return
        self.routes.append((segments, handler))

    def resolve(self, path):
        if not isinstance(path, str):
            raise ValueError("path must be a string")
        if not path.startswith("/"):
            raise ValueError("path must start with '/'")

        # On resolve only, discard the first '?' or '#' and everything after.
        cut = len(path)
        for index, char in enumerate(path):
            if char == "?" or char == "#":
                cut = index
                break
        parts = _segments(path[:cut])

        best_handler = None
        best_params = None
        best_static = -1

        for pattern, handler in self.routes:
            if len(pattern) != len(parts):
                continue
            params = {}
            for wanted, actual in zip(pattern, parts):
                if wanted.startswith(":"):
                    # A parameter captures one nonempty (normalized) segment.
                    params[wanted[1:]] = actual
                elif wanted != actual:
                    break
            else:
                # Matched.  Prefer the most static segments; strict '>' keeps
                # earlier registrations on ties.
                static_count = _static_count(pattern)
                if static_count > best_static:
                    best_static = static_count
                    best_handler = handler
                    best_params = params

        if best_handler is None:
            raise KeyError(path)
        return best_handler, best_params

