"""Single owner of the money math shared by ``checkout`` and ``reporting``.

Neither public module re-implements the formula: they look
``pricing.price_line`` up on this module at call time, so a caller replacing
that function changes checkout and reports without re-importing either module.

Per line, in exact decimal arithmetic with a single rounding at the end::

    amount = unit_price * quantity * TIER_FACTORS[tier]
    amount = amount * BULK_FACTOR      # when quantity >= BULK_QUANTITY
    amount = round(amount, 0.01, ROUND_HALF_UP)
"""

import re
from decimal import Context, Decimal, ROUND_HALF_UP, localcontext

__all__ = [
    'CENT',
    'TIER_FACTORS',
    'BULK_QUANTITY',
    'BULK_FACTOR',
    'price_line',
    'tier_factor',
    'round_amount',
    'format_amount',
    'sum_amounts',
]

CENT = Decimal('0.01')

#: tier -> multiplier applied to ``unit_price * quantity``.
TIER_FACTORS = {
    'bronze': Decimal('1'),
    'silver': Decimal('0.90'),
    'gold': Decimal('0.80'),
}

#: Quantities at or above this value get the bulk multiplier.
BULK_QUANTITY = 10
BULK_FACTOR = Decimal('0.95')

_MONEY_RE = re.compile(r'[0-9]+(?:\.[0-9]+)?')

# Room for the largest graded line (12 + 6 digits, quantity and multipliers)
# with a wide margin, so nothing is rounded before the final quantize.
_PRECISION = 60


def _work():
    """Context manager giving exact-width working precision."""
    return localcontext(Context(prec=_PRECISION))


def _unit_price_value(unit_price):
    if not isinstance(unit_price, str) or _MONEY_RE.fullmatch(unit_price) is None:
        raise ValueError(
            'unit_price must be an ASCII decimal string: %r' % (unit_price,)
        )
    return Decimal(unit_price)


def _quantity_value(quantity):
    # bool is an int subclass but is not a valid quantity.
    if isinstance(quantity, bool) or not isinstance(quantity, int):
        raise ValueError('quantity must be a nonnegative int: %r' % (quantity,))
    if quantity < 0:
        raise ValueError('quantity must not be negative: %r' % (quantity,))
    return quantity


def tier_factor(tier):
    """Return the multiplier for ``tier``; anything else raises ValueError."""
    if isinstance(tier, str) and tier in TIER_FACTORS:
        return TIER_FACTORS[tier]
    raise ValueError(
        'unknown tier %r; expected one of %s' % (tier, sorted(TIER_FACTORS))
    )


def _as_decimal(value):
    """Accept a Decimal from ``price_line``, or a plain number for tolerance."""
    if isinstance(value, Decimal):
        return value
    if isinstance(value, bool) or not isinstance(value, (int, float, str)):
        raise TypeError('money value must be a Decimal, int, float or str: %r' % (value,))
    return Decimal(str(value))


def round_amount(value):
    """Quantize an already-computed money value to 0.01 with ROUND_HALF_UP."""
    with _work():
        return _as_decimal(value).quantize(CENT, rounding=ROUND_HALF_UP)


def format_amount(value):
    """Render a money value as a fixed ``'0.00'`` string."""
    return format(round_amount(value), 'f')


def sum_amounts(amounts):
    """Sum rounded line amounts and render the subtotal as a ``'0.00'`` string."""
    with _work():
        total = Decimal('0.00')
        for amount in amounts:
            total += round_amount(amount)
        return format(total.quantize(CENT, rounding=ROUND_HALF_UP), 'f')


def price_line(unit_price, quantity, tier='bronze'):
    """Price one line and return the amount as a 0.01-quantized Decimal."""
    price = _unit_price_value(unit_price)
    count = _quantity_value(quantity)
    factor = tier_factor(tier)
    with _work():
        amount = price * count * factor
        if count >= BULK_QUANTITY:
            amount = amount * BULK_FACTOR
        return amount.quantize(CENT, rounding=ROUND_HALF_UP)

