from decimal import Decimal, ROUND_HALF_UP

import pricing


def quote(items, tier='bronze'):
    lines = []
    total = Decimal('0.00')
    for item in items:
        amount = pricing.price_line(item['unit_price'], item['quantity'], tier)
        total += amount
        lines.append({'sku': item['sku'], 'amount': format(amount, '.2f')})
    return {
        'lines': lines,
        'total': format(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f'),
    }

