        self.assertIsInstance(result, Decimal)
        self.assertEqual(result.as_tuple().exponent, -2)

    def test_default_tier_is_bronze(self):
        self.assertEqual(pricing.price_line('2.00', 3), Decimal('6.00'))

    def test_bulk_discount_at_threshold(self):
        self.assertEqual(pricing.price_line('1.00', 9), Decimal('9.00'))
        self.assertEqual(pricing.price_line('1.00', 10), Decimal('9.50'))
        self.assertEqual(pricing.price_line('1.00', 11), Decimal('10.45'))

    def test_half_up_rounding(self):
        self.assertEqual(pricing.price_line('0.005', 1), Decimal('0.01'))
        self.assertEqual(pricing.price_line('0.015', 1), Decimal('0.02'))
        self.assertEqual(pricing.price_line('0.004', 1), Decimal('0.00'))

    def test_round_once_after_all_factors(self):
        # 2.345 * 10 * 0.90 * 0.95 = 20.04975 -> 20.05
        self.assertEqual(pricing.price_line('2.345', 10, 'silver'), Decimal('20.05'))

    def test_zero_values(self):
        self.assertEqual(pricing.price_line('0', 0), Decimal('0.00'))
        self.assertEqual(pricing.price_line('0.00', 1000, 'gold'), Decimal('0.00'))

    def test_large_exact_money(self):
        value = '123456789012.123456'
        expected = (Decimal(value) * 1000 * Decimal('0.95')).quantize(Decimal('0.01'))
        self.assertEqual(pricing.price_line(value, 1000, 'bronze'), expected)
        expected9 = (Decimal(value) * 9).quantize(Decimal('0.01'))
        self.assertEqual(pricing.price_line(value, 9, 'bronze'), expected9)

    def test_invalid_money(self):
        for bad in ['', '.', '.5', '5.', '1e3', '-1', '+1', ' 1', '1 ', 'abc', '1,2', '1.2.3', '0x1']:
            with self.assertRaises(ValueError, msg=bad):
                pricing.price_line(bad, 1)
        with self.assertRaises(ValueError):
            pricing.price_line(1, 1)
        with self.assertRaises(ValueError):
            pricing.price_line(None, 1)

    def test_invalid_quantity(self):
        for bad in [-1, True, False, 1.0, '1', None, 2.5]:
            with self.assertRaises(ValueError, msg=repr(bad)):
                pricing.price_line('1', bad)

    def test_invalid_tier(self):
        for bad in ['platinum', 'BRONZE', '', None, 1, ['bronze']]:
            with self.assertRaises(ValueError, msg=repr(bad)):
                pricing.price_line('1', 1, bad)


