import re
from decimal import Decimal, ROUND_HALF_UP, localcontext

MONEY_RE = re.compile(r'[0-9]+(?:\.[0-9]+)?')
CENT = Decimal('0.01')

TIER_FACTORS = {
    'bronze': Decimal('1'),
    'silver': Decimal('0.90'),
    'gold': Decimal('0.80'),
}

BULK_QUANTITY = 10
BULK_FACTOR = Decimal('0.95')


def _valid_money(value):
    return isinstance(value, str) and MONEY_RE.fullmatch(value) is not None


def _valid_quantity(value):
    if isinstance(value, bool):
        return False
    return type(value) is int and value >= 0


def _valid_tier(tier):
    return isinstance(tier, str) and tier in TIER_FACTORS


def price_line(unit_price, quantity, tier='bronze'):
    if not _valid_money(unit_price):
        raise ValueError(f'invalid unit_price: {unit_price!r}')
    if not _valid_quantity(quantity):
        raise ValueError(f'invalid quantity: {quantity!r}')
    if not _valid_tier(tier):
        raise ValueError(f'invalid tier: {tier!r}')

    with localcontext() as ctx:
        ctx.prec = 80
        amount = Decimal(unit_price) * quantity * TIER_FACTORS[tier]
        if quantity >= BULK_QUANTITY:
            amount = amount * BULK_FACTOR
        return amount.quantize(CENT, rounding=ROUND_HALF_UP)

