files.coverage.py:
"""Normalize half-open interval coverage.

Public API (see README.md):

    coverage(intervals, start, end) -> {
        'merged': [[lo, hi], ...],   # sorted, merged, clipped to [start, end)
        'gaps':   [[lo, hi], ...],   # sorted nonempty complement in [start, end)
        'covered': int,              # integer length of the merged union
    }

All bounds and endpoints are plain integers (``bool`` is rejected).  Interval
items must be two-element ``list``/``tuple`` objects with ``lo <= hi``.  Any
malformed input raises :class:`_InvalidInput`, which is a subclass of both
``ValueError`` (the documented type) and ``TypeError`` (the type Python
conventionally uses for unusable argument types).

Only integer arithmetic is used, so arbitrarily large operands are supported
and no integer inside the window is ever enumerated.  The caller's data is
never mutated: nothing is sorted in place and interval items are read, not
written.
"""

from __future__ import annotations

__all__ = ["coverage"]


class _InvalidInput(ValueError, TypeError):
    """Malformed argument passed to :func:`coverage`.

    Derived from ``ValueError`` because that is what the public contract
    documents for invalid input; also derived from ``TypeError`` so callers
    expecting the usual Python error for an unusable argument type (for
    example a non-iterable ``intervals``) keep working.
    """


def _as_int(value, what):
    """Return ``value`` if it is a genuine integer, else raise."""
    # bool is a subclass of int but is explicitly not a valid bound/endpoint.
    if isinstance(value, bool) or not isinstance(value, int):
        raise _InvalidInput(
            "%s must be an integer, got %r of type %s"
            % (what, value, type(value).__name__)
        )
    return value


def _as_interval(item, index):
    """Validate one input item and return it as a plain ``(lo, hi)`` tuple."""
    if not isinstance(item, (list, tuple)):
        raise _InvalidInput(
            "intervals[%d] must be a two-element list or tuple, got %r of type %s"
            % (index, item, type(item).__name__)
        )
    if len(item) != 2:
        raise _InvalidInput(
            "intervals[%d] must have exactly two elements, got %d"
            % (index, len(item))
        )
    lo = _as_int(item[0], "intervals[%d][0]" % index)
    hi = _as_int(item[1], "intervals[%d][1]" % index)
    if lo > hi:
        raise _InvalidInput(
            "intervals[%d] has lo > hi: [%r, %r]" % (index, lo, hi)
        )
    return (lo, hi)


def _validated_copy(intervals):
    """Consume any finite iterable once, validating every item.

    Validation is deliberately independent of ``start``/``end``: an invalid
    interval raises even when it lies wholly outside the requested window, so
    the whole input is checked before anything is clipped.
    """
    try:
        iterator = iter(intervals)
    except TypeError:
        raise _InvalidInput(
            "intervals must be a finite iterable of [lo, hi] pairs, got %r"
            % (intervals,)
        ) from None

    items = []
    while True:
        try:
            item = next(iterator)
        except StopIteration:
            break
        except TypeError as exc:  # a custom iterator may reject next()
            raise _InvalidInput(
                "intervals must be a finite iterable of [lo, hi] pairs: %s" % (exc,)
            ) from exc
        # Appending keeps caller order untouched and works for generators.
        items.append(_as_interval(item, len(items)))
    return items


def coverage(intervals, start, end):
    """Clip, merge and reduce half-open intervals against ``[start, end)``.

    Returns a fresh dict with keys ``merged``, ``gaps`` and ``covered``.  Every
    returned interval is a two-element list ``[lo, hi]`` with ``lo < hi``;
    ``merged`` is sorted and neither overlapping nor touching, ``gaps`` is the
    sorted complement inside the window, and ``covered`` is the total integer
    length of ``merged``.
    """
    start = _as_int(start, "start")
    end = _as_int(end, "end")
    if start > end:
        raise _InvalidInput(
            "start must be <= end, got start=%r, end=%r" % (start, end)
        )

    items = _validated_copy(intervals)

    # Clip to [start, end) and drop the empty results.  Comparisons only, so
    # huge integers are handled without enumerating anything.
    clipped = []
    for lo, hi in items:
        clo = start if lo < start else lo
        chi = end if hi > end else hi
        if clo < chi:
            clipped.append((clo, chi))

    clipped.sort()

    # Merge overlapping or touching intervals: a successor continues the
    # current run whenever it starts at or before the run's end.
    merged = []
    for lo, hi in clipped:
        if merged and lo <= merged[-1][1]:
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    # Gaps are the sorted nonempty complement of the merged union.
    gaps = []
    cursor = start
    for lo, hi in merged:
        if lo > cursor:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    covered = 0
    for lo, hi in merged:
        covered += hi - lo

    return {"merged": merged, "gaps": gaps, "covered": covered}

