"""Extra checks for the README contract, beyond public_tests.py.

Run from anywhere:  python tests/test_coverage.py
"""

import copy
import os
import sys
import unittest

# Make sure the workspace copy of coverage.py wins over any installed package
# with the same name.
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if ROOT not in sys.path:
    sys.path.insert(0, ROOT)

from coverage import coverage  # noqa: E402


class HappyPath(unittest.TestCase):
    def test_smoke_contract(self):
        self.assertEqual(
            coverage([[3, 5], [-2, 2], [2, 4]], 0, 7),
            {"merged": [[0, 5]], "gaps": [[5, 7]], "covered": 5},
        )

    def test_empty_window(self):
        self.assertEqual(
            coverage([[0, 5]], 3, 3),
            {"merged": [], "gaps": [], "covered": 0},
        )
        self.assertEqual(
            coverage([], 0, 0),
            {"merged": [], "gaps": [], "covered": 0},
        )

    def test_empty_interval_list(self):
        self.assertEqual(
            coverage([], 0, 10),
            {"merged": [], "gaps": [[0, 10]], "covered": 0},
        )

    def test_empty_intervals_ignored(self):
        self.assertEqual(
            coverage([[2, 2], [0, 3], [3, 3]], 0, 5)["merged"],
            [[0, 3]],
        )

    def test_disjoint_merged_and_gaps(self):
        self.assertEqual(
            coverage([[0, 1], [4, 6]], 0, 10),
            {"merged": [[0, 1], [4, 6]], "gaps": [[1, 4], [6, 10]], "covered": 3},
        )

    def test_touching_intervals_merge(self):
        self.assertEqual(
            coverage([[0, 2], [2, 4], [4, 4]], 0, 10)["merged"],
            [[0, 4]],
        )

    def test_overlapping_unsorted_input(self):
        self.assertEqual(
            coverage([[7, 9], [1, 5], [3, 8]], 0, 10),
            {"merged": [[1, 9]], "gaps": [[0, 1], [9, 10]], "covered": 8},
        )

    def test_window_inside_one_interval(self):
        self.assertEqual(
            coverage([[-100, 100]], 3, 7),
            {"merged": [[3, 7]], "gaps": [], "covered": 4},
        )

    def test_covers_window_exactly(self):
        self.assertEqual(
            coverage([[0, 5], [5, 10]], 0, 10),
            {"merged": [[0, 10]], "gaps": [], "covered": 10},
        )

    def test_valid_intervals_outside_window_are_dropped(self):
        self.assertEqual(
            coverage([[-100, -50], [50, 100], [2, 3]], 0, 10),
            {"merged": [[2, 3]], "gaps": [[0, 2], [3, 10]], "covered": 1},
        )

    def test_negative_bounds_and_endpoints(self):
        self.assertEqual(
            coverage([[-5, -3], [-4, 0]], -6, -1),
            {"merged": [[-5, -1]], "gaps": [[-6, -5]], "covered": 4},
        )

    def test_nested_and_duplicate_intervals(self):
        self.assertEqual(
            coverage([[1, 9], [2, 3], [1, 9], [4, 5]], 0, 10)["merged"],
            [[1, 9]],
        )

    def test_single_point_window(self):
        self.assertEqual(
            coverage([[0, 5]], 2, 3),
            {"merged": [[2, 3]], "gaps": [], "covered": 1},
        )
        self.assertEqual(
            coverage([[5, 6]], 2, 3),
            {"merged": [], "gaps": [[2, 3]], "covered": 0},
        )

    def test_generator_input(self):
        gen = ((lo, hi) for lo, hi in [(0, 1), (1, 2)])
        self.assertEqual(
            coverage(gen, 0, 4)["merged"],
            [[0, 2]],
        )

    def test_tuple_items_accepted(self):
        self.assertEqual(coverage(((0, 1),), 0, 2)["merged"], [[0, 1]])

    def test_covered_matches_gaps(self):
        for intervals, start, end in [
            ([[0, 3], [5, 6]], 0, 10),
            ([[-7, 2]], -10, 10),
            ([[1, 2], [2, 3], [9, 11]], 0, 12),
        ]:
            result = coverage([list(i) for i in intervals], start, end)
            gap_len = sum(hi - lo for lo, hi in result["gaps"])
            self.assertEqual(result["covered"] + gap_len, end - start)
            self.assertEqual(
                result["covered"], sum(hi - lo for lo, hi in result["merged"])
            )

    def test_return_shapes(self):
        result = coverage([[0, 1]], 0, 3)
        self.assertEqual(set(result), {"merged", "gaps", "covered"})
        self.assertIsInstance(result["covered"], int)
        for key in ("merged", "gaps"):
            self.assertIsInstance(result[key], list)
            for item in result[key]:
                self.assertIsInstance(item, list)
                self.assertEqual(len(item), 2)
                self.assertTrue(all(isinstance(v, int) for v in item))
                self.assertLess(item[0], item[1])


class LargeIntegers(unittest.TestCase):
    def test_no_enumeration_of_huge_ranges(self):
        huge = 10 ** 100
        self.assertEqual(
            coverage([[-(10 ** 80), 10 ** 80]], -huge, huge),
            {"merged": [[-(10 ** 80), 10 ** 80]],
             "gaps": [[-huge, -(10 ** 80)], [10 ** 80, huge]],
             "covered": 2 * 10 ** 80},
        )

    def test_adjacent_huge_intervals(self):
        big = 10 ** 60
        self.assertEqual(
            coverage([[big, big + 1], [big + 1, big + 5]], 0, big + 10),
            {"merged": [[big, big + 5]],
             "gaps": [[0, big], [big + 5, big + 10]],
             "covered": 5},
        )


class InvalidInput(unittest.TestCase):
    def assertInvalid(self, *args):
        with self.assertRaises(ValueError):
            coverage(*args)

    def test_lo_greater_than_hi(self):
        self.assertInvalid([[5, 1]], 0, 10)
        self.assertInvalid([[0, 0], [9, 2]], 0, 10)

    def test_invalid_interval_outside_window_still_raises(self):
        self.assertInvalid([[100, 50]], 0, 5)
        self.assertInvalid([[-9, -20]], 0, 5)

    def test_start_greater_than_end(self):
        self.assertInvalid([[0, 1]], 5, 4)

    def test_bool_invalid_everywhere(self):
        self.assertInvalid([[0, 1]], True, 5)
        self.assertInvalid([[0, 1]], 0, False)
        self.assertInvalid([[True, 3]], 0, 5)
        self.assertInvalid([[0, False]], 0, 5)

    def test_non_integer_bounds_and_endpoints(self):
        self.assertInvalid([[0, 1]], 0.0, 5)
        self.assertInvalid([[0, 1]], 0, 5.5)
        self.assertInvalid([[0, 1]], "0", 5)
        self.assertInvalid([[0, 1]], None, 5)
        self.assertInvalid([[0.5, 3]], 0, 5)
        self.assertInvalid([[0, "3"]], 0, 5)

    def test_malformed_items(self):
        self.assertInvalid([0, 1], 0, 5)          # item is an int
        self.assertInvalid([[0, 1, 2]], 0, 5)     # too many elements
        self.assertInvalid([[0]], 0, 5)           # too few elements
        self.assertInvalid([[]], 0, 5)
        self.assertInvalid(["ab"], 0, 5)          # strings are not intervals
        self.assertInvalid([[0, 1], None], 0, 5)
        self.assertInvalid([{0, 1}], 0, 5)        # sets are not list/tuple

    def test_non_iterable_intervals(self):
        self.assertInvalid(None, 0, 5)
        self.assertInvalid(5, 0, 5)
        # The documented error is ValueError; TypeError is also satisfied.
        with self.assertRaises(TypeError):
            coverage(None, 0, 5)

    def test_error_is_plain_valueerror_subclass(self):
        with self.assertRaises(ValueError) as ctx:
            coverage([[3, 1]], 0, 5)
        self.assertIsInstance(ctx.exception, ValueError)


class NoMutation(unittest.TestCase):
    def test_caller_data_untouched(self):
        intervals = [[7, 9], [1, 5], [3, 8]]
        snapshot = copy.deepcopy(intervals)
        coverage(intervals, 0, 10)
        self.assertEqual(intervals, snapshot)
        self.assertEqual(
            [type(item).__name__ for item in intervals], ["list", "list", "list"]
        )

    def test_result_not_aliased_to_input(self):
        intervals = [[0, 5]]
        result = coverage(intervals, 0, 10)
        result["merged"][0][1] = 99
        self.assertEqual(intervals, [[0, 5]])

    def test_repeated_calls_are_independent(self):
        first = coverage([[0, 2]], 0, 5)
        second = coverage([[0, 2]], 0, 5)
        first["merged"].append([10, 20])
        self.assertEqual(second, {"merged": [[0, 2]], "gaps": [[2, 5]], "covered": 2})


def _brute_force(intervals, start, end):
    """Reference implementation: enumerate every integer in the window."""
    covered_points = set()
    for lo, hi in intervals:
        for point in range(lo, hi):
            if start <= point < end:
                covered_points.add(point)

    merged = []
    for point in sorted(covered_points):
        if merged and point == merged[-1][1]:
            merged[-1][1] = point + 1
        else:
            merged.append([point, point + 1])

    gaps = []
    cursor = start
    for lo, hi in merged:
        if lo > cursor:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    return {"merged": merged, "gaps": gaps, "covered": len(covered_points)}


class AgainstBruteForce(unittest.TestCase):
    def test_random_small_cases_match_reference(self):
        import random

        rng = random.Random(20260929)
        for _ in range(3000):
            low, high = -6, 6
            start = rng.randint(low, high)
            end = rng.randint(start, high)
            intervals = []
            for _ in range(rng.randint(0, 5)):
                lo = rng.randint(low, high)
                hi = rng.randint(lo, high)
                intervals.append([lo, hi])
            expected = _brute_force(intervals, start, end)
            actual = coverage([list(i) for i in intervals], start, end)
            self.assertEqual(
                actual,
                expected,
                "mismatch for intervals=%r start=%r end=%r" % (intervals, start, end),
            )

    def test_random_huge_int_cases_match_reference(self):
        import random

        rng = random.Random(7)
        offset = 10 ** 30
        for _ in range(500):
            start = offset + rng.randint(-4, 4)
            end = offset + rng.randint(start - offset, 4)
            intervals = []
            for _ in range(rng.randint(0, 4)):
                lo = offset + rng.randint(-4, 4)
                hi = offset + rng.randint(lo - offset, 4)
                intervals.append([lo, hi])
            expected = _brute_force(
                [[lo - offset, hi - offset] for lo, hi in intervals],
                start - offset,
                end - offset,
            )
            for key in ("merged", "gaps"):
                for item in expected[key]:
                    item[0] += offset
                    item[1] += offset
            actual = coverage(intervals, start, end)
            self.assertEqual(
                actual,
                expected,
                "mismatch for intervals=%r start=%r end=%r" % (intervals, start, end),
            )


if __name__ == "__main__":
    unittest.main(verbosity=2)

